#[derive(Debug, Deserialize, Default)]
struct PauseResumeRequest {
    #[serde(default)]
    reason: Option<String>,
}

/// Request body for `POST /admin/schedules/workflow`.
#[derive(Debug, Deserialize)]
struct CreateWorkflowScheduleRequest {
    workflow_name: String,
    schedule_expr: String,
    /// IANA timezone the cron expression is evaluated in (e.g.
    /// `"America/Los_Angeles"`, `"Europe/London"`, `"UTC"`).
    ///
    /// Defaults to `"UTC"`, preserving the pre-existing behavior.
    /// Ignored for `interval:*` and `manual` expressions.
    #[serde(default = "default_timezone")]
    timezone: String,
    #[serde(default)]
    input: serde_json::Value,
    #[serde(default)]
    catchup: bool,
    #[serde(default = "default_max_active_runs")]
    max_active_runs: u32,
    #[serde(default)]
    paused: bool,
    #[serde(default = "default_queue_name")]
    queue_name: String,
    /// Jitter window in seconds. `0` disables jitter (default).
    #[serde(default)]
    jitter_secs: u64,
    /// Overlap policy string (e.g. `"skip"`, `"buffer_one"`, `"buffer_all"`,
    /// `"cancel_other"`, `"terminate_other"`). Defaults to `"skip"`.
    #[serde(default = "default_overlap_policy")]
    overlap_policy: String,
    /// Maximum buffered slots under `BufferAll`. Defaults to `100`.
    #[serde(default = "default_buffer_all_max")]
    buffer_all_max: u32,
    /// Optional named calendar for business-day / holiday filtering (issue #337).
    #[serde(default)]
    calendar: Option<String>,
    /// What to do when the fire date is excluded by the calendar.
    /// Valid values: `"skip"`, `"run_next_business_day"`, `"run_prev_business_day"`.
    #[serde(default = "default_skip_policy")]
    skip_policy: String,
    /// Auto-pause after this many consecutive `FAILED`/`TIMED_OUT` execution completions.
    /// `null` (the default) disables auto-pause (issue #360).
    #[serde(default)]
    consecutive_failure_limit: Option<u32>,
    /// Absolute UTC cutoff for this schedule (issue #478).
    /// When `next_run_at >= end_at` the scheduler stops firing and marks the schedule
    /// exhausted. `null` (the default) = no cutoff.
    #[serde(default)]
    end_at: Option<chrono::DateTime<chrono::Utc>>,
    /// Total run budget for this schedule (issue #478).
    /// Once `runs_started` reaches `max_runs` the schedule is exhausted. `null` = no limit.
    #[serde(default)]
    max_runs: Option<u32>,
    /// Bounded catchup policy mode (issue #484): one of `"skip_all"`,
    /// `"most_recent"`, `"window"`, `"unbounded"`. When omitted the legacy
    /// `catchup` bool governs catchup behaviour and the policy columns are left
    /// NULL. `"window"` additionally reads `catchup_window_secs`.
    ///
    /// Like every other field on this upsert endpoint, omitting it on an update
    /// resets the stored policy to "unset" (legacy-bool semantics); send the
    /// desired mode explicitly to retain a bounded policy.
    #[serde(default)]
    catchup_policy: Option<String>,
    /// Window length in seconds for `catchup_policy = "window"` (issue #484).
    /// Ignored for every other mode. `null`/omitted defaults to `0`.
    #[serde(default)]
    catchup_window_secs: Option<i64>,
    /// Schedule-level workflow retry policy (issue #523). When set, scheduler
    /// fires, backfills, and trigger-now runs for this schedule auto-retry a
    /// `FAILED` run per this policy (taking precedence over the workflow-type
    /// default). Like every other field on this upsert endpoint, omitting it on
    /// an update resets the stored policy to NULL (falling back to the
    /// workflow-type default); send it explicitly to retain a schedule policy.
    #[serde(default)]
    retry_policy: Option<autumn_harvest::RetryPolicy>,
}

/// Deserialize helper for tri-state PATCH fields: a field that is absent from
/// the JSON body deserializes to `None` (via `#[serde(default)]`, "leave
/// unchanged"), while an explicit JSON `null` deserializes to `Some(None)`
/// ("clear to NULL") and a value to `Some(Some(v))`.
#[allow(clippy::option_option)] // deliberate serde tri-state: absent vs null vs value
fn deserialize_tristate<'de, T, D>(deserializer: D) -> Result<Option<Option<T>>, D::Error>
where
    T: serde::Deserialize<'de>,
    D: serde::Deserializer<'de>,
{
    Ok(Some(Option::<T>::deserialize(deserializer)?))
}

/// Request body for `PATCH /admin/schedules/{id}` (issue #771).
///
/// Every field is optional — only provided fields change. Nullable fields
/// (`calendar`, `consecutive_failure_limit`, `end_at`, `max_runs`,
/// `catchup_policy`, `retry_policy`) are tri-state: absent = unchanged,
/// explicit JSON `null` = clear.
///
/// `workflow_name` is accepted structurally only so the handler can reject it
/// with a targeted 400 — the workflow type bound to a schedule is not
/// editable (that is a new schedule, not an edit).
///
/// `Option<Option<T>>` (`clippy::option_option`) is the standard serde
/// double-`Option` PATCH idiom: the outer `Option` distinguishes an absent
/// field from an explicit JSON `null`, mirroring the core
/// `WorkflowSchedulePatch` contract.
///
/// `deny_unknown_fields`: because every field is optional, a typo'd field
/// name (`"scheduleexpr"`) would otherwise deserialize to an all-`None` body
/// and 200-no-op with a SUCCEEDED audit row — a silent failure. The rejection
/// surfaces as a 400 via the handler's `Result<Json<…>, JsonRejection>`
/// extractor (see [`update_schedule_handler`]).
#[allow(clippy::option_option)]
#[derive(Debug, Default, Deserialize)]
#[serde(deny_unknown_fields)]
struct UpdateWorkflowScheduleRequest {
    /// NOT editable — present in the struct only to produce a targeted 400.
    workflow_name: Option<String>,
    /// New schedule expression, mirroring the create vocabulary:
    /// bare cron / `cron:<expr>` / `cron_tz:<tz>:<expr>` / `interval:<secs>` /
    /// `manual`.
    schedule_expr: Option<String>,
    /// New IANA timezone for the cron expression. When provided without
    /// `schedule_expr`, the stored cron expression is re-anchored in this
    /// timezone. Ignored for interval/manual schedules (mirrors create).
    timezone: Option<String>,
    input: Option<serde_json::Value>,
    catchup: Option<bool>,
    max_active_runs: Option<u32>,
    queue_name: Option<String>,
    jitter_secs: Option<u64>,
    overlap_policy: Option<String>,
    buffer_all_max: Option<u32>,
    #[serde(default, deserialize_with = "deserialize_tristate")]
    calendar: Option<Option<String>>,
    skip_policy: Option<String>,
    #[serde(default, deserialize_with = "deserialize_tristate")]
    consecutive_failure_limit: Option<Option<u32>>,
    #[serde(default, deserialize_with = "deserialize_tristate")]
    end_at: Option<Option<chrono::DateTime<chrono::Utc>>>,
    #[serde(default, deserialize_with = "deserialize_tristate")]
    max_runs: Option<Option<u32>>,
    #[serde(default, deserialize_with = "deserialize_tristate")]
    catchup_policy: Option<Option<String>>,
    catchup_window_secs: Option<i64>,
    #[serde(default, deserialize_with = "deserialize_tristate")]
    retry_policy: Option<Option<autumn_harvest::RetryPolicy>>,
}

fn default_queue_name() -> String {
    "default".to_string()
}

fn default_timezone() -> String {
    "UTC".to_string()
}

const fn default_max_active_runs() -> u32 {
    1
}

fn default_overlap_policy() -> String {
    "skip".to_string()
}

fn default_skip_policy() -> String {
    "skip".to_string()
}

const fn default_buffer_all_max() -> u32 {
    100
}

/// Workflow execution states that the management API recognises in `state=`
/// filters. Anything outside this list is rejected with `400 Bad Request`.
pub(crate) const KNOWN_WORKFLOW_STATES: &[&str] = &[
    "RUNNING",
    "PAUSED",
    "COMPLETED",
    "FAILED",
    "CANCELLED",
    "TIMED_OUT",
    "CONTINUED_AS_NEW",
    "TERMINATED",
    // Issue #964. Both are returned by `GET /workflows`, so both must be
    // filterable: a state the API emits but rejects as a filter value is a
    // listing an operator can see and cannot narrow.
    "MIGRATING",
    "MIGRATED",
];

