const MAX_WORKFLOW_LIMIT: i64 = 200;
const DEFAULT_WORKFLOW_CHILDREN_LIMIT: usize = 50;
const MAX_WORKFLOW_CHILDREN_LIMIT: usize = 500;
const MAX_WORKFLOW_CHILDREN_DEPTH: u8 = 5;
const DEFAULT_EXTERNAL_HANDOFF_LIMIT: i64 = 100;
const MAX_EXTERNAL_HANDOFF_LIMIT: i64 = 500;
const DEFAULT_HISTORY_BATCH_EXPORT_LIMIT: usize = 100;
const MAX_HISTORY_BATCH_EXPORT_LIMIT: usize = 1_000;

/// Sort direction for `GET /workflows` (issue #498).
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub(crate) enum WorkflowSortOrder {
    #[default]
    Desc,
    Asc,
}

/// Numeric comparison operator for a search-attribute predicate (issue #506).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum CmpOp {
    Gt,
    Gte,
    Lt,
    Lte,
}

/// A typed comparison/set predicate over a single top-level search-attribute key
/// (issue #506). Parsed from a `search_attr_filter=key:op:value` query param.
#[derive(Debug, Clone)]
pub(crate) enum SearchAttrPredicate {
    /// `key:eq:value` — typed equality (numeric/bool/string coercion).
    Eq { key: String, value: Value },
    /// `key:ne:value` — key present and typed value differs.
    Ne { key: String, value: Value },
    /// `key:{gt,gte,lt,lte}:value` — numeric comparison. `value` is the
    /// validated, trimmed numeric *text* (not an f64): it is bound and cast
    /// `::numeric` in SQL so the comparison stays exact even for integers
    /// beyond f64's 2^53 mantissa (issue #506 review).
    Cmp {
        key: String,
        op: CmpOp,
        value: String,
    },
    /// `key:in:v1,v2,…` — membership in a typed set.
    In { key: String, values: Vec<Value> },
    /// `key:exists` — key is present with any value.
    Exists { key: String },
}

/// Decoded keyset cursor for `GET /workflows` (issue #498).
#[derive(Debug, Clone)]
pub(crate) struct WorkflowListCursor {
    pub(crate) created_at: chrono::DateTime<chrono::Utc>,
    pub(crate) exec_id: uuid::Uuid,
}

/// Response envelope returned when any pagination param is present (issue #498).
#[derive(Debug, Serialize)]
pub struct WorkflowListPage {
    pub workflows: Vec<StalledWorkflowRow>,
    pub next_cursor: Option<String>,
    /// Cross-shard completeness of this page (issue #756). Additive: always
    /// present on the paginated object shape, `complete` on the happy path.
    pub status: FanoutStatus,
    /// Shards that could not be queried, named with a reason (issue #756).
    /// Empty on the happy path.
    pub unavailable_shards: Vec<UnavailableShard>,
}

// A parsed query-param bag: each bool is an independent opt-in filter flag
// (`?sla_breached=true`, `?nd_blocked=true`, ...), not encodable state — a
// state machine or enums would obscure the 1:1 query-param mapping.
#[allow(clippy::struct_excessive_bools)]
#[derive(Debug, Default, Clone)]
pub(crate) struct WorkflowFilters {
    pub(crate) limit: i64,
    pub(crate) states: Vec<String>,
    pub(crate) workflow_name: Option<String>,
    pub(crate) search_attrs: Vec<Value>,
    /// Typed comparison/set predicates over search attributes (issue #506).
    /// Combined with `AND` against each other and against the legacy
    /// `search_attrs` containment predicates above.
    pub(crate) search_attr_predicates: Vec<SearchAttrPredicate>,
    pub(crate) started_after: Option<chrono::DateTime<chrono::Utc>>,
    pub(crate) started_before: Option<chrono::DateTime<chrono::Utc>>,
    /// Prefix match on the execution UUID cast to text (e.g. "abc123").
    pub(crate) exec_id_prefix: Option<String>,
    pub(crate) owner: Option<String>,
    pub(crate) severity: Option<String>,
    pub(crate) failure_cause: Option<String>,
    /// Only return executions with no event progress for this many minutes (issue #486).
    pub(crate) no_progress_minutes: Option<i64>,
    /// When true, include executions whose sole pending work is a future-dated
    /// durable timer (correctly sleeping). Default false = exclude sleepers.
    pub(crate) include_sleeping: bool,
    /// When true, return only executions whose soft SLA has been breached (#487).
    pub(crate) sla_breached: bool,
    /// When true, return only RUNNING executions currently blocked on replay
    /// non-determinism (issue #603).
    pub(crate) nd_blocked: bool,
    /// When true, return only executions currently under an active legal hold
    /// (issue #747).
    pub(crate) legal_hold: bool,
    /// Only return executions with the given `start_source` provenance (issue #740).
    /// A validated bounded `snake_case` string (a known `StartSource` variant or
    /// the literal `"unknown"`, which matches NULL / pre-upgrade rows via `IS NULL`).
    pub(crate) start_source: Option<String>,
    /// Only return executions with at least this many recorded events (issue #493).
    /// General-purpose: composes freely with `state=`/`order=`/pagination and
    /// sorts in the caller's chosen order. Distinct from `history_bloat_min_events`
    /// below (issue #704) — the two must never share a query-parameter name, or a
    /// caller combining `state=COMPLETED&min_history_events=N` (or pagination)
    /// would silently get the wrong results instead of the documented ones.
    pub(crate) min_history_events: Option<u64>,
    /// Operator early-warning discovery for workflow history bloat (issue
    /// #704, AC1): a dedicated, non-composable path returning only live
    /// (non-terminal) executions with at least this many recorded events,
    /// sorted by current history size descending. Deliberately a SEPARATE
    /// field/query-param from `min_history_events` above — see its doc
    /// comment for why reusing that name would be a regression.
    pub(crate) history_bloat_min_events: Option<u64>,
    /// Sort direction (issue #498). Default: `Desc`.
    pub(crate) order: WorkflowSortOrder,
    /// Keyset cursor decoded from the `cursor` query param (issue #498).
    pub(crate) cursor: Option<WorkflowListCursor>,
    /// True when any pagination param (`cursor`, `page_size`, `order`) is
    /// present; drives the opt-in response envelope (issue #498).
    pub(crate) paginated: bool,
}

impl WorkflowFilters {
    pub(crate) const fn with_limit(mut self, limit: i64) -> Self {
        self.limit = limit;
        self
    }
}

