/// Request body for `POST /admin/gates`.
#[derive(Debug, Deserialize)]
struct CreateGateRequest {
    /// Scope kind: `"fleet"` | `"workflow_name"` | `"queue"` | `"shard_id"` | `"owner"`
    scope_kind: String,
    /// Scope value: omit for fleet; required for all other kinds.
    scope_value: Option<String>,
    /// Required human-readable reason; included in blocked-caller errors.
    reason: String,
    /// Optional extended message for the Vantage UI.
    message: Option<String>,
    /// ISO 8601 timestamp after which the gate self-clears.
    expires_at: Option<chrono::DateTime<chrono::Utc>>,
}

/// `GET /admin/gates` — list all active (non-lifted) gates.
async fn list_gates_handler(
    Extension(api_state): Extension<HarvestApiState>,
) -> axum::response::Response {
    let pool = match api_state.storage_pool() {
        Ok(p) => p,
        Err(e) => return AutumnError::internal_server_error(e).into_response(),
    };
    let mut conn = match acquire_conn(pool.default_pool()).await {
        Ok(c) => c,
        Err(e) => return e.into_response(),
    };

    match admission_gate_db::list_gates(&mut conn).await {
        Ok(rows) => {
            let views: Vec<AdmissionGateView> = rows.iter().map(AdmissionGateView::from).collect();
            // issue #618 (AC5): surface the discoverable start-producer contract
            // alongside the active gates so an operator can see which in-process
            // producers honour a gate and which are exempt-by-design (with a
            // rationale) without reading source.
            let producers = autumn_harvest::admission_gate::producer_contract();
            (
                StatusCode::OK,
                Json(serde_json::json!({ "gates": views, "producers": producers })),
            )
                .into_response()
        }
        Err(e) => AutumnError::internal_server_error(e).into_response(),
    }
}

/// `POST /admin/gates` — create an admission gate.
#[allow(clippy::too_many_lines)]
/// Reconcile the in-memory admission-gate cache after a create/lift that was
/// already persisted to the DB and written through to the snapshot
/// (`apply_created`/`apply_lifted`), given the result of the follow-up full
/// reload.
///
/// On a successful reload, `refresh()` the snapshot — replacing it with the
/// authoritative active-gate list (reconciling other replicas' concurrent
/// changes) and setting `initialized = true`, which RECOVERS from any prior
/// fail-closed. Returns the reloaded active-gate count so the caller can emit the
/// `admission_gates_active` metric.
///
/// On a reload FAILURE, arm fail-closed (issue #618, F-round22, superseding the
/// F-round16 "do NOT arm fail-closed" decision) and return `None`. While the gate
/// table is momentarily unreadable, `check()` — the API / fresh-admission path,
/// which CAN retry — must return the synthetic block until a successful refresh
/// reconciles ALL active gates, rather than serving fresh admissions from a
/// snapshot that reflects only this replica's local write-through delta and could
/// be MISSING another replica's gate (e.g. a Fleet gate created on replica B just
/// before this replica creates a narrower gate and then fails its own reload — a
/// non-matching start would otherwise slip past B's gate uncounted). On the lift
/// path this briefly re-blocks the just-lifted work; that OVER-BLOCK is the correct
/// conservative behaviour for a safety control during a gate-table outage
/// (over-block briefly rather than leak), bounded by the <=1s background refresh.
///
/// The already-applied write-through delta is retained and load-bearing:
/// `check_cached` — the completion-trigger / in-flight-continuation path, which
/// CANNOT retry — ignores the fail-closed flag (round 3) and reads the snapshot,
/// so the just-created gate is still matched (and the just-lifted gate no longer
/// matched) there, and no in-flight work is permanently dropped. Fail-closed is
/// therefore transient: the next successful reload re-arms `initialized = true`.
fn reconcile_gate_cache_after_mutation<E: std::fmt::Display>(
    cache: &autumn_harvest::AdmissionGateCache,
    op: &'static str,
    reload: Result<Vec<autumn_harvest::AdmissionGate>, E>,
) -> Option<i64> {
    match reload {
        Ok(fresh) => {
            let count = i64::try_from(fresh.len()).unwrap_or(0);
            cache.refresh(fresh);
            Some(count)
        }
        Err(e) => {
            cache.set_fail_closed();
            tracing::warn!(
                error = %e,
                op,
                "admission gate cache full refresh failed after gate mutation; arming \
                 fail-closed so check() blocks fresh admissions until the gate table is \
                 readable again; the write-through delta keeps check_cached accurate for \
                 the mutated gate (completion triggers unaffected); background refresh recovers"
            );
            None
        }
    }
}

async fn create_gate_handler(
    Extension(api_state): Extension<HarvestApiState>,
    headers: axum::http::HeaderMap,
    Json(body): Json<CreateGateRequest>,
) -> axum::response::Response {
    let (actor, source, request_id) = audit_context(&headers, &api_state);

    // Validate scope/value combination before parsing: fleet scope must not
    // carry a scope_value (a caller who accidentally sends both intends a
    // narrower scope but would create a fleet-wide gate instead).
    if body.scope_kind == "fleet" && body.scope_value.is_some() {
        return (
            StatusCode::BAD_REQUEST,
            Json(serde_json::json!({
                "error": "scope_kind 'fleet' must not include a scope_value"
            })),
        )
            .into_response();
    }

    let Some(scope) = GateScope::from_db(&body.scope_kind, body.scope_value.as_deref()) else {
        return (
            StatusCode::BAD_REQUEST,
            Json(serde_json::json!({
                "error": format!("unknown scope_kind '{}'", body.scope_kind)
            })),
        )
            .into_response();
    };

    let pool = match api_state.storage_pool() {
        Ok(p) => p,
        Err(e) => return AutumnError::internal_server_error(e).into_response(),
    };
    let mut conn = match acquire_conn(pool.default_pool()).await {
        Ok(c) => c,
        Err(e) => return e.into_response(),
    };

    let result = admission_gate_db::create_gate(
        &mut conn,
        &scope,
        &body.reason,
        body.message.as_deref(),
        &actor,
        body.expires_at,
    )
    .await;

    match result {
        Ok(gate) => {
            // Write-through the just-persisted gate into the in-memory snapshot
            // (issue #618, F-round16) BEFORE the full refresh, so this replica
            // honours the new gate even if the follow-up load fails. The gate was
            // persisted to the DB first (create_gate above), so the snapshot is now
            // accurate for this change regardless of the refresh outcome. This
            // matters most for the completion-trigger path (check_cached), which
            // does NOT retry after a synthetic fail-closed block — a stale-open
            // snapshot here would durably MISS the new gate.
            api_state.gate_cache().apply_created(gate.clone());
            // Reconcile any OTHER concurrent changes with a full refresh; on a
            // reload failure arm fail-closed so check() blocks fresh admissions
            // until the gate table is readable (issue #618, F-round22 — see
            // reconcile_gate_cache_after_mutation for the full rationale). The
            // round-16 write-through above is retained: check_cached ignores the
            // fail-closed flag (round 3) and keeps honouring the just-created gate,
            // so completion triggers / in-flight continuation are unaffected.
            if let Some(count) = reconcile_gate_cache_after_mutation(
                api_state.gate_cache().as_ref(),
                "create",
                admission_gate_db::load_active_gates(&mut conn).await,
            ) && let Ok(rt) = api_state.runtime()
            {
                rt.registry()
                    .telemetry()
                    .metrics
                    .record_admission_gates_active(count);
            }

            let gate_id_str = gate.id.to_string();
            let ar = NewAuditRecord {
                actor: &actor,
                operation: OP_GATE_CREATE,
                target_type: TARGET_GATE,
                target_id: Some(gate_id_str.as_str()),
                route_or_command: "POST /admin/gates",
                request_id: request_id.as_deref(),
                idempotency_key: None,
                status: STATUS_SUCCEEDED,
                error_summary: None,
                shard_id: None,
                source: &source,
            };
            let _ = audit::insert_audit(&mut conn, &ar).await;

            (StatusCode::CREATED, Json(AdmissionGateView::from(gate))).into_response()
        }
        Err(e) => {
            let err_str = e.to_string();
            let ar = NewAuditRecord {
                actor: &actor,
                operation: OP_GATE_CREATE,
                target_type: TARGET_GATE,
                target_id: None,
                route_or_command: "POST /admin/gates",
                request_id: request_id.as_deref(),
                idempotency_key: None,
                status: STATUS_FAILED,
                error_summary: Some(err_str.as_str()),
                shard_id: None,
                source: &source,
            };
            let _ = audit::insert_audit(&mut conn, &ar).await;
            match e {
                autumn_harvest::error::HarvestError::Config(msg) => {
                    // Active gate cap exceeded → 429; other config errors → 400.
                    let status = if msg.contains("active gate limit") {
                        StatusCode::TOO_MANY_REQUESTS
                    } else {
                        StatusCode::BAD_REQUEST
                    };
                    (status, Json(serde_json::json!({ "error": msg }))).into_response()
                }
                other => AutumnError::internal_server_error(other).into_response(),
            }
        }
    }
}

/// `DELETE /admin/gates/{id}` — lift (soft-delete) an admission gate.
async fn lift_gate_handler(
    Extension(api_state): Extension<HarvestApiState>,
    Path(id): Path<uuid::Uuid>,
    headers: axum::http::HeaderMap,
) -> axum::response::Response {
    let (actor, source, request_id) = audit_context(&headers, &api_state);

    let pool = match api_state.storage_pool() {
        Ok(p) => p,
        Err(e) => return AutumnError::internal_server_error(e).into_response(),
    };
    let mut conn = match acquire_conn(pool.default_pool()).await {
        Ok(c) => c,
        Err(e) => return e.into_response(),
    };

    let id_str = id.to_string();
    match admission_gate_db::lift_gate(&mut conn, id, &actor).await {
        Ok(Some(_gate)) => {
            // Write-through the lift into the in-memory snapshot (issue #618,
            // F-round16) BEFORE the full refresh, so the just-lifted gate stops
            // matching on this replica even if the follow-up load fails. The lift
            // was persisted to the DB first (lift_gate above). This is what makes a
            // lift durable for the completion-trigger path (check_cached): a
            // stale-open snapshot here would keep dropping targets as
            // admission_blocked against a gate the operator already lifted.
            api_state.gate_cache().apply_lifted(id);
            // Reconcile any OTHER concurrent changes with a full refresh; on a
            // reload failure arm fail-closed so check() blocks fresh admissions
            // until the gate table is readable (issue #618, F-round22 — see
            // reconcile_gate_cache_after_mutation for the full rationale). This
            // briefly OVER-BLOCKS — including re-blocking the just-lifted work —
            // which is the correct conservative behaviour for a safety control
            // during a gate-table outage (over-block briefly rather than risk
            // leaking a start past another replica's still-active gate), bounded by
            // the <=1s refresh. The round-16 write-through above is retained:
            // check_cached ignores the fail-closed flag (round 3) and the lifted
            // gate no longer matches there, so in-flight continuation is unaffected.
            if let Some(count) = reconcile_gate_cache_after_mutation(
                api_state.gate_cache().as_ref(),
                "lift",
                admission_gate_db::load_active_gates(&mut conn).await,
            ) && let Ok(rt) = api_state.runtime()
            {
                rt.registry()
                    .telemetry()
                    .metrics
                    .record_admission_gates_active(count);
            }

            let ar = NewAuditRecord {
                actor: &actor,
                operation: OP_GATE_LIFT,
                target_type: TARGET_GATE,
                target_id: Some(id_str.as_str()),
                route_or_command: "DELETE /admin/gates/{id}",
                request_id: request_id.as_deref(),
                idempotency_key: None,
                status: STATUS_SUCCEEDED,
                error_summary: None,
                shard_id: None,
                source: &source,
            };
            let _ = audit::insert_audit(&mut conn, &ar).await;

            (StatusCode::OK, Json(serde_json::json!({ "lifted": true }))).into_response()
        }
        // Gate not found or already lifted — return lifted:false for idempotent
        // cleanup; callers do not need to pre-check existence before lifting.
        Ok(None) => (StatusCode::OK, Json(serde_json::json!({ "lifted": false }))).into_response(),
        Err(e) => AutumnError::internal_server_error(e).into_response(),
    }
}

// ── Scoped API tokens (issue #942) ───────────────────────────────────────────

/// Request body for `POST /admin/tokens`.
#[derive(serde::Deserialize)]
struct CreateTokenRequest {
    name: String,
    /// `"read"` or `"mutate"` — the verb-level scope drawn from the route
    /// classification. Defaults to `read` (least privilege) when omitted.
    #[serde(default = "default_token_scope")]
    scope: String,
    /// Optional expiry; an expired token is rejected 401 on the next request.
    #[serde(default)]
    expires_at: Option<chrono::DateTime<chrono::Utc>>,
}

fn default_token_scope() -> String {
    "read".to_string()
}

/// `POST /admin/tokens` — mint a scoped API token. The plaintext secret is
/// returned **exactly once** in this response; only its hash is stored.
async fn create_token_handler(
    Extension(api_state): Extension<HarvestApiState>,
    headers: axum::http::HeaderMap,
    Json(body): Json<CreateTokenRequest>,
) -> axum::response::Response {
    let (actor, source, request_id) = audit_context(&headers, &api_state);

    let Some(scope) = crate::api_token::TokenScope::from_db(&body.scope) else {
        return (
            StatusCode::BAD_REQUEST,
            Json(serde_json::json!({
                "error": format!("unknown scope '{}' (expected 'read' or 'mutate')", body.scope)
            })),
        )
            .into_response();
    };

    let pool = match api_state.storage_pool() {
        Ok(p) => p,
        Err(e) => return AutumnError::internal_server_error(e).into_response(),
    };
    let mut conn = match acquire_conn(pool.default_pool()).await {
        Ok(c) => c,
        Err(e) => return e.into_response(),
    };

    match crate::api_token::create_token(&mut conn, &body.name, scope, body.expires_at, &actor)
        .await
    {
        Ok(mint) => {
            let id_str = mint.view.id.to_string();
            let ar = NewAuditRecord {
                actor: &actor,
                operation: OP_TOKEN_CREATE,
                target_type: TARGET_TOKEN,
                target_id: Some(id_str.as_str()),
                route_or_command: "POST /admin/tokens",
                request_id: request_id.as_deref(),
                idempotency_key: None,
                status: STATUS_SUCCEEDED,
                error_summary: None,
                shard_id: None,
                source: &source,
            };
            let _ = audit::insert_audit(&mut conn, &ar).await;

            // Flatten the metadata view and attach the one-time secret.
            let mut value =
                serde_json::to_value(&mint.view).unwrap_or_else(|_| serde_json::json!({}));
            if let Some(obj) = value.as_object_mut() {
                obj.insert("secret".to_string(), serde_json::json!(mint.secret()));
            }
            (StatusCode::CREATED, Json(value)).into_response()
        }
        Err(e) => {
            let err_str = e.to_string();
            let ar = NewAuditRecord {
                actor: &actor,
                operation: OP_TOKEN_CREATE,
                target_type: TARGET_TOKEN,
                target_id: None,
                route_or_command: "POST /admin/tokens",
                request_id: request_id.as_deref(),
                idempotency_key: None,
                status: STATUS_FAILED,
                error_summary: Some(err_str.as_str()),
                shard_id: None,
                source: &source,
            };
            let _ = audit::insert_audit(&mut conn, &ar).await;
            // Do NOT surface the raw DB error text (a unique-violation `DETAIL`
            // echoes the row) into the HTTP response; the real error is captured
            // in the audit `error_summary` above. Return a clean generic 500.
            (
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(serde_json::json!({ "error": "failed to create api token" })),
            )
                .into_response()
        }
    }
}

/// `GET /admin/tokens` — list all tokens as metadata-only views (no
/// secret/hash). Not audited (a read).
async fn list_tokens_handler(
    Extension(api_state): Extension<HarvestApiState>,
) -> axum::response::Response {
    let pool = match api_state.storage_pool() {
        Ok(p) => p,
        Err(e) => return AutumnError::internal_server_error(e).into_response(),
    };
    let mut conn = match acquire_conn(pool.default_pool()).await {
        Ok(c) => c,
        Err(e) => return e.into_response(),
    };
    match crate::api_token::list_tokens(&mut conn).await {
        Ok(views) => (StatusCode::OK, Json(views)).into_response(),
        Err(e) => AutumnError::internal_server_error(e).into_response(),
    }
}

/// `DELETE /admin/tokens/{id}` — revoke a token. Idempotent; revocation is
/// effective on the next request (no grant cache).
async fn revoke_token_handler(
    Extension(api_state): Extension<HarvestApiState>,
    Path(id): Path<uuid::Uuid>,
    headers: axum::http::HeaderMap,
) -> axum::response::Response {
    let (actor, source, request_id) = audit_context(&headers, &api_state);

    let pool = match api_state.storage_pool() {
        Ok(p) => p,
        Err(e) => return AutumnError::internal_server_error(e).into_response(),
    };
    let mut conn = match acquire_conn(pool.default_pool()).await {
        Ok(c) => c,
        Err(e) => return e.into_response(),
    };

    let id_str = id.to_string();
    match crate::api_token::revoke_token(&mut conn, id).await {
        Ok(revoked) => {
            let ar = NewAuditRecord {
                actor: &actor,
                operation: OP_TOKEN_REVOKE,
                target_type: TARGET_TOKEN,
                target_id: Some(id_str.as_str()),
                route_or_command: "DELETE /admin/tokens/{id}",
                request_id: request_id.as_deref(),
                idempotency_key: None,
                status: STATUS_SUCCEEDED,
                error_summary: None,
                shard_id: None,
                source: &source,
            };
            let _ = audit::insert_audit(&mut conn, &ar).await;
            (
                StatusCode::OK,
                Json(serde_json::json!({ "revoked": revoked })),
            )
                .into_response()
        }
        Err(e) => AutumnError::internal_server_error(e).into_response(),
    }
}

// ── Business-id route variants (issue #805) ──────────────────────────────────
//
// Embedders assign a business `(workflow_name, workflow_id)` at start. These
// routes let them act on the *current* run by that pair — no list-then-act
// round-trip, and always the live run even after a continue-as-new/reset fork
// (a cached `exec_id` targets the stale predecessor). Each handler resolves the
// pair to an `ExecutionId` and DELEGATES to the existing `exec_id` handler so
// the exec-id surface stays byte-for-byte backward compatible. Every response
// carries the resolved `execution_id` — always in the `X-Harvest-Execution-Id`
// header (uniform AC4 guarantee, covers empty-body cases), and in the JSON body
// wherever there is one.

/// Response header carrying the resolved internal `execution_id` on every
/// business-id (`/workflows/by-id/...`) response (issue #805, AC4).
pub(crate) const HEADER_EXECUTION_ID: &str = "x-harvest-execution-id";

/// Attach the resolved `execution_id` to a response via the
/// `X-Harvest-Execution-Id` header. Uniform across every by-id route so AC4
/// holds even for empty-body responses (e.g. `/result` 204).
fn insert_exec_id_header(resp: &mut axum::response::Response, exec_id: ExecutionId) {
    if let Ok(value) = axum::http::HeaderValue::from_str(&exec_id.to_string()) {
        resp.headers_mut().insert(
            axum::http::HeaderName::from_static(HEADER_EXECUTION_ID),
            value,
        );
    }
}

/// Convert a delegated `Result<T, AutumnError>` into a response and stamp the
/// resolved `execution_id` header. Used by by-id handlers whose delegate
/// already carries `execution_id` (or an equivalent id) in its body.
fn finalize_by_id<T: IntoResponse>(
    out: Result<T, AutumnError>,
    exec_id: ExecutionId,
) -> axum::response::Response {
    let mut resp = match out {
        Ok(value) => value.into_response(),
        Err(error) => error.into_response(),
    };
    insert_exec_id_header(&mut resp, exec_id);
    resp
}

/// Resolve `(workflow_name, workflow_id)` to the current run's `ExecutionId`
/// (issue #805). Returns a clean `404` (never `500`) when the key is genuinely
/// unknown, and `503` (never a false `404`) when a shard cannot be queried.
///
/// **Shard strategy — fan out across every *expected* shard.** We deliberately
/// query every shard rather than trusting a single rendezvous-hash fast path:
/// `ShardRouter::pick_for_new_workflow` can drift from where a run actually
/// lives once the writable shard subset changes (see the KNOWN LIMITATION on
/// `pick_for_idempotency_key`), so a fast-path-then-miss design could resolve a
/// live run to `404`. The shard set comes from
/// [`shard_fanout::expected_shards`], which unions this process's live pools
/// with the router's `readable_shards`/`default_shard` — so a shard the router
/// knows about but for which this process has no pool yet (mid a shard-add
/// rollout) is not silently skipped.
///
/// **Correctness over availability (multi-shard degraded mode).** An *expected*
/// shard with no pool in this process, or one whose connection cannot be
/// acquired, yields a `503` for the whole resolution rather than a silent skip:
/// we cannot rule out that the run lives on the un-queried shard, so returning
/// `404` would be a false negative. On the single-shard default this never
/// triggers (the one shard always has a pool), and `expected_shards` yields
/// exactly one shard so this reduces to one query at no cost. A future
/// refinement could try the rendezvous-hash shard first and only fan out on a
/// miss, but that is out of scope for this slice.
///
/// The fan-out is **sequential** — one connection held at a time — so it is
/// safe against a pool sized down to a single connection. Per-shard candidates
/// are merged by the pure `select_resolved_run` (active-run-first, else
/// most-recent terminal).
pub(crate) async fn resolve_workflow_by_business_id(
    api_state: &HarvestApiState,
    workflow_name: &str,
    workflow_id: &str,
) -> Result<ExecutionId, AutumnError> {
    // issue #1353: reject an empty workflow_id uniformly across the whole
    // by-id route family, before any shard fan-out. `matchit` cannot bind an
    // empty FINAL path segment. The base route (`GET .../{name}/{id}`)
    // therefore 404'd at the router for such a value. Every sibling route
    // resolved it instead, because its empty id lands on a non-final segment
    // (e.g. `.../{id}/stack`). That made the family inconsistent for one
    // identifier. Rejecting it here, ahead of resolution, makes all ten
    // routes answer 400 alike, regardless of which router-matching quirk let
    // the request through.
    if workflow_id.is_empty() {
        return Err(AutumnError::bad_request_msg(
            "workflow_id must not be empty",
        ));
    }
    let pools = crate::shard_fanout::pools_by_shard(api_state);
    let expected = crate::shard_fanout::expected_shards(api_state, &pools);
    let mut candidates = Vec::new();
    for shard_id in &expected {
        let Some(shard_pool) = pools.get(shard_id) else {
            // The router knows this shard but this process has no pool for it
            // yet (mid a shard-add rollout). We cannot query it, so we cannot
            // rule out that the run lives there — fail closed with 503 rather
            // than risk a false 404.
            return Err(AutumnError::service_unavailable_msg(format!(
                "shard {shard_id} has no configured storage pool; cannot resolve \
                 (workflow_name={workflow_name}, workflow_id={workflow_id}) \
                 without risking a false 404"
            )));
        };
        // `acquire_conn` maps a pool/connection failure to 503, so a genuinely
        // unreachable shard also fails closed rather than being silently skipped.
        let mut conn = acquire_conn(shard_pool).await?;
        if let Some(run) = autumn_harvest::execution::resolve_execution_id_by_workflow_id(
            &mut conn,
            workflow_name,
            workflow_id,
        )
        .await
        .map_err(map_error)?
        {
            candidates.push(run);
        }
    }
    autumn_harvest::execution::select_resolved_run(candidates)
        .map(|run| run.exec_id)
        .ok_or_else(|| {
            map_error(HarvestError::NotFound(format!(
                "no workflow execution for (workflow_name={workflow_name}, \
                 workflow_id={workflow_id})"
            )))
        })
}

/// Write a `STATUS_FAILED` audit row for a *mutating* by-id handler whose
/// `(workflow_name, workflow_id)` resolution failed (issue #805, review FIX 4).
///
/// Mirrors the exec-id handlers' failed-attempt audit posture (e.g.
/// `cancel_workflow`'s malformed-id and cancel-error paths, which both write a
/// `STATUS_FAILED` row before returning): without this, a signal/cancel/pause/
/// resume against an unresolvable business id left no audit trail, an
/// asymmetry with the exec-id surface. Best-effort — a failed audit write never
/// fails the request. The audit `target_id` is the unresolved business id
/// (`"{workflow_name}/{workflow_id}"`) and `route_or_command` is the by-id
/// route so the failed attempt's provenance is accurate.
async fn audit_by_id_resolution_failure(
    api_state: &HarvestApiState,
    headers: &axum::http::HeaderMap,
    operation: &str,
    route: &str,
    workflow_name: &str,
    workflow_id: &str,
) {
    let (actor, source, request_id) = audit_context(headers, api_state);
    let target_id = format!("{workflow_name}/{workflow_id}");
    if let Ok(pool) = api_state.storage_pool()
        && let Ok(mut conn) = acquire_conn(pool.default_pool()).await
    {
        let ar = NewAuditRecord {
            actor: &actor,
            operation,
            target_type: TARGET_WORKFLOW,
            target_id: Some(target_id.as_str()),
            route_or_command: route,
            request_id: request_id.as_deref(),
            idempotency_key: None,
            status: STATUS_FAILED,
            error_summary: Some("business-id resolution failed"),
            shard_id: None,
            source: &source,
        };
        let _ = audit::insert_audit(&mut conn, &ar).await;
    }
}

/// `GET /workflows/by-id/{workflow_name}/{workflow_id}` — describe by business id.
async fn get_workflow_by_id(
    Extension(api_state): Extension<HarvestApiState>,
    Path((workflow_name, workflow_id)): Path<(String, String)>,
    headers: axum::http::HeaderMap,
    maybe_session: Option<Extension<Session>>,
) -> axum::response::Response {
    let exec_id =
        match resolve_workflow_by_business_id(&api_state, &workflow_name, &workflow_id).await {
            Ok(id) => id,
            Err(error) => return error.into_response(),
        };
    let out = get_workflow(
        Extension(api_state),
        Path(exec_id.to_string()),
        headers,
        maybe_session,
    )
    .await;
    finalize_by_id(out, exec_id)
}

/// `GET /workflows/by-id/{workflow_name}/` — literal-trailing-slash form of
/// the base by-id route (issue #1353). `matchit` cannot bind an empty FINAL
/// path segment as `{workflow_id}`. This shape therefore needs its own
/// registration to reach a handler at all. Without it, axum answers a
/// structural 404 ("no route matches") before any application code runs.
/// Delegates to [`get_workflow_by_id`] with `workflow_id = ""`, which
/// [`resolve_workflow_by_business_id`] now rejects 400 -- the same answer
/// every other by-id route gives for an empty id.
async fn get_workflow_by_id_trailing_slash(
    Extension(api_state): Extension<HarvestApiState>,
    Path(workflow_name): Path<String>,
    headers: axum::http::HeaderMap,
    maybe_session: Option<Extension<Session>>,
) -> axum::response::Response {
    get_workflow_by_id(
        Extension(api_state),
        Path((workflow_name, String::new())),
        headers,
        maybe_session,
    )
    .await
}

/// `GET /workflows/by-id/{workflow_name}/{workflow_id}/result` — terminal-output
/// projection by business id (issue #805). Header carries `execution_id` on all
/// responses; the 200/204/long-poll semantics of the delegate are preserved
/// unchanged.
async fn get_workflow_result_by_id(
    Extension(api_state): Extension<HarvestApiState>,
    Path((workflow_name, workflow_id)): Path<(String, String)>,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
    headers: axum::http::HeaderMap,
    maybe_session: Option<Extension<Session>>,
) -> axum::response::Response {
    // Issue #1151 review: reject a malformed query string up front, before
    // the business-id resolution DB lookup below -- otherwise an unknown
    // workflow_id or an unreachable shard would mask the malformed query
    // behind a 404/503 instead of the documented 400, and the lookup would
    // run for a request that was always going to be rejected. The delegate
    // (`get_workflow_result`) decodes `raw_query` again once resolution
    // succeeds; this is a cheap, side-effect-free re-parse, not a
    // functional duplication.
    if let Err(response) =
        crate::strict_query::decode_or_autumn_error_response(raw_query.as_deref())
    {
        return response;
    }
    let exec_id =
        match resolve_workflow_by_business_id(&api_state, &workflow_name, &workflow_id).await {
            Ok(id) => id,
            Err(error) => return error.into_response(),
        };
    let mut resp = get_workflow_result(
        Extension(api_state),
        Path(exec_id.to_string()),
        axum::extract::RawQuery(raw_query),
        headers,
        maybe_session,
    )
    .await;
    insert_exec_id_header(&mut resp, exec_id);
    resp
}

