/// `POST /workflows/by-id/{workflow_name}/{workflow_id}/signal/{signal_name}` —
/// signal by business id (issue #805). The `SignalAck` body is re-wrapped to
/// include the resolved `execution_id`.
async fn signal_workflow_by_id(
    Extension(api_state): Extension<HarvestApiState>,
    Path((workflow_name, workflow_id, signal_name)): Path<(String, String, String)>,
    Query(query): Query<SignalQuery>,
    headers: axum::http::HeaderMap,
    Json(payload): Json<Value>,
) -> axum::response::Response {
    let exec_id =
        match resolve_workflow_by_business_id(&api_state, &workflow_name, &workflow_id).await {
            Ok(id) => id,
            Err(error) => {
                audit_by_id_resolution_failure(
                    &api_state,
                    &headers,
                    OP_WORKFLOW_SIGNAL,
                    "POST /workflows/by-id/{workflow_name}/{workflow_id}/signal/{signal_name}",
                    &workflow_name,
                    &workflow_id,
                )
                .await;
                return error.into_response();
            }
        };
    let result = signal_workflow(
        Extension(api_state),
        Path((exec_id.to_string(), signal_name)),
        Query(query),
        headers,
        Json(payload),
    )
    .await;
    // `signal_workflow` returns an opaque `Response` (issue #610 changed its
    // signature so it can emit the field-level schema-validation 400 body). On
    // the 202 success path re-wrap the `{ok, signal_delivered}` ack body with
    // `execution_id`; on any error/validation response forward it verbatim.
    // Either way stamp the resolved execution id header.
    let (parts, body) = result.into_parts();
    if parts.status == axum::http::StatusCode::ACCEPTED {
        let ack = axum::body::to_bytes(body, usize::MAX)
            .await
            .ok()
            .and_then(|bytes| serde_json::from_slice::<Value>(&bytes).ok())
            .unwrap_or_else(|| serde_json::json!({}));
        let mut out = serde_json::json!({
            "execution_id": exec_id.to_string(),
            "ok": ack.get("ok").cloned().unwrap_or(Value::Bool(true)),
            "signal_delivered": ack
                .get("signal_delivered")
                .cloned()
                .unwrap_or(Value::Bool(false)),
        });
        // Forward the #843 routed-live-attempt marker when the inner handler
        // set it, so a by-id caller can also see that the retry chain moved.
        //
        // The two ids are deliberately distinct and both correct:
        // `execution_id` (and the `X-Harvest-Execution-Id` header) is what the
        // BUSINESS KEY resolved to — the #805 contract, unchanged — while
        // `routed_execution_id` is the live attempt the signal actually landed
        // on. Rewriting the #805 id to the routed one would make a by-id
        // caller's recorded handle drift to an inner attempt.
        if let Some(routed) = ack.get("routed_execution_id").cloned()
            && let Some(map) = out.as_object_mut()
        {
            map.insert("routed_execution_id".to_string(), routed);
        }
        let mut resp = (parts.status, Json(out)).into_response();
        insert_exec_id_header(&mut resp, exec_id);
        resp
    } else {
        let mut resp = axum::response::Response::from_parts(parts, body);
        insert_exec_id_header(&mut resp, exec_id);
        resp
    }
}

/// `GET /workflows/by-id/{workflow_name}/{workflow_id}/query/{query_name}` —
/// query by business id (issue #805). The opaque handler return is wrapped as
/// `{ "execution_id": ..., "result": <value> }`.
async fn query_workflow_by_id(
    Extension(api_state): Extension<HarvestApiState>,
    Path((workflow_name, workflow_id, query_name)): Path<(String, String, String)>,
) -> axum::response::Response {
    let exec_id =
        match resolve_workflow_by_business_id(&api_state, &workflow_name, &workflow_id).await {
            Ok(id) => id,
            Err(error) => return error.into_response(),
        };
    let result = query_workflow(
        Extension(api_state),
        Path((exec_id.to_string(), query_name)),
    )
    .await;
    match result {
        Ok(Json(value)) => {
            let body = serde_json::json!({
                "execution_id": exec_id.to_string(),
                "result": value,
            });
            let mut resp = Json(body).into_response();
            insert_exec_id_header(&mut resp, exec_id);
            resp
        }
        Err(error) => {
            let mut resp = error.into_response();
            insert_exec_id_header(&mut resp, exec_id);
            resp
        }
    }
}

