#[allow(clippy::too_many_lines)]
async fn delete_schedule(
    Extension(api_state): Extension<HarvestApiState>,
    Path(id): Path<String>,
    headers: axum::http::HeaderMap,
) -> Result<Json<BasicAck>, AutumnError> {
    use autumn_harvest::models::HarvestSchedule;
    use autumn_harvest::schema::harvest_schedules::dsl;

    let (actor, source, request_id) = audit_context(&headers, &api_state);
    let route = "DELETE /admin/schedules/{id}";
    let pool = api_state.storage_pool().map_err(map_error)?;

    let id = match parse_uuid(&id, "schedule id") {
        Ok(u) => u,
        Err(e) => {
            schedule_delete_audit_failed(
                &pool,
                &actor,
                &source,
                request_id.as_deref(),
                &id,
                "malformed schedule id",
            )
            .await;
            return Err(e);
        }
    };
    let id_str = id.to_string();

    let mut deleted_count = 0usize;
    for (_shard, shard_pool) in pool.iter_shards() {
        let mut conn = acquire_conn(shard_pool).await?;
        let row: Option<HarvestSchedule> = dsl::harvest_schedules
            .find(id)
            .select(HarvestSchedule::as_select())
            .first(&mut conn)
            .await
            .optional()
            .map_err(database_error)
            .map_err(map_error)?;
        let Some(row) = row else {
            continue;
        };
        if row.dag_name.is_some() {
            schedule_delete_audit_failed(
                &pool,
                &actor,
                &source,
                request_id.as_deref(),
                &id_str,
                "dag-managed schedule cannot be deleted via API",
            )
            .await;
            return Err(AutumnError::bad_request_msg(format!(
                "schedule {id} is managed by the DAG catalog and cannot be deleted via API; \
                 remove the DAG definition to stop scheduling"
            )));
        }
        if let Some(ref wf_name) = row.workflow_name {
            let runtime = api_state.runtime().map_err(map_error)?;
            let is_code_managed = runtime
                .workflow_schedules()
                .iter()
                .any(|ws| ws.workflow_name == *wf_name);
            if is_code_managed {
                schedule_delete_audit_failed(
                    &pool,
                    &actor,
                    &source,
                    request_id.as_deref(),
                    &id_str,
                    "code-managed schedule cannot be deleted via API",
                )
                .await;
                return Err(AutumnError::bad_request_msg(format!(
                    "schedule {id} is managed by the in-process workflow schedule catalog \
                     and cannot be deleted via API; it will be re-created on the next \
                     scheduler tick"
                )));
            }
        }
        let n = diesel::delete(dsl::harvest_schedules.find(id))
            .execute(&mut conn)
            .await
            .map_err(database_error)
            .map_err(map_error)?;
        deleted_count += n;
        if deleted_count > 0 {
            let ar = NewAuditRecord {
                actor: &actor,
                operation: OP_SCHEDULE_DELETE,
                target_type: TARGET_SCHEDULE,
                target_id: Some(id_str.as_str()),
                route_or_command: route,
                request_id: request_id.as_deref(),
                idempotency_key: None,
                status: STATUS_SUCCEEDED,
                error_summary: None,
                shard_id: None,
                source: &source,
            };
            audit::insert_audit(&mut conn, &ar)
                .await
                .map_err(map_error)?;
            break;
        }
    }

    if deleted_count == 0 {
        schedule_delete_audit_failed(
            &pool,
            &actor,
            &source,
            request_id.as_deref(),
            &id_str,
            "schedule not found",
        )
        .await;
        return Err(AutumnError::not_found_msg(format!("schedule {id}")));
    }
    Ok(Json(BasicAck { ok: true }))
}

// ── Schedule trigger-now (issue #343) ─────────────────────────────────────────

/// Optional request body for `POST /admin/schedules/{id}/trigger`.
#[derive(Debug, Default, Deserialize)]
struct ScheduleTriggerRequest {
    /// Free-text reason recorded in the audit trail.
    #[serde(default)]
    reason: Option<String>,
    /// Optional override of the schedule's configured overlap policy.
    #[serde(default)]
    overlap_policy: Option<String>,
}

/// Query parameters for `POST /admin/schedules/{id}/trigger`.
#[derive(Debug, Default, Deserialize)]
struct TriggerScheduleQuery {
    /// If `true`, trigger even if the schedule is paused.
    #[serde(default)]
    force: bool,
}

/// Response for `POST /admin/schedules/{id}/trigger`.
#[derive(Debug, Serialize)]
struct ScheduleTriggerResponse {
    /// Present when an execution was actually started; absent when skipped by overlap policy.
    #[serde(skip_serializing_if = "Option::is_none")]
    execution_id: Option<uuid::Uuid>,
    workflow_id: String,
    triggered_at: chrono::DateTime<chrono::Utc>,
    /// `"fired"` when a new execution was started, `"skipped_overlap"` when the
    /// effective overlap policy suppressed the run.
    outcome: String,
}

#[allow(clippy::too_many_lines)]
async fn trigger_schedule_now(
    Extension(api_state): Extension<HarvestApiState>,
    Path(id): Path<String>,
    Query(query): Query<TriggerScheduleQuery>,
    headers: axum::http::HeaderMap,
    body: Option<Json<ScheduleTriggerRequest>>,
) -> Result<Json<ScheduleTriggerResponse>, AutumnError> {
    let (actor, source, request_id) = audit_context(&headers, &api_state);
    let route = "POST /admin/schedules/{id}/trigger";
    let body = body.map(|Json(b)| b).unwrap_or_default();

    let schedule_id = parse_uuid(&id, "schedule id")?;
    let pool = api_state.storage_pool().map_err(map_error)?;
    let runtime = api_state.runtime().map_err(map_error)?;

    // Load the schedule AND which shard it lives on. Budget accounting writes must
    // target the same shard — the schedule row may not be on the default shard for
    // unified-DAG schedules (issue #478).
    let (schedule, schedule_shard) =
        load_schedule_by_id_with_shard(&api_state, schedule_id).await?;

    let schedule_display_name = schedule
        .workflow_name
        .as_deref()
        .or(schedule.dag_name.as_deref())
        .unwrap_or("")
        .to_string();

    // Reject paused schedules unless ?force=true is passed.
    if schedule.is_paused && !query.force {
        if let Ok(mut conn) = acquire_conn(pool.default_pool()).await {
            let ar = NewAuditRecord {
                actor: &actor,
                operation: OP_SCHEDULE_TRIGGER,
                target_type: TARGET_SCHEDULE,
                target_id: Some(id.as_str()),
                route_or_command: route,
                request_id: request_id.as_deref(),
                idempotency_key: None,
                status: STATUS_FAILED,
                error_summary: Some("rejected_paused"),
                shard_id: None,
                source: &source,
            };
            let _ = audit::insert_audit(&mut conn, &ar).await;
        }
        runtime
            .registry
            .telemetry()
            .metrics
            .record_schedule_manual_trigger(&schedule_display_name, "rejected_paused");
        return Err(AutumnError::bad_request_msg(format!(
            "schedule {schedule_id} is paused; pass ?force=true to trigger a paused schedule"
        ))
        .with_status(axum::http::StatusCode::CONFLICT));
    }

    // Reject exhausted schedules (issue #478). Manual triggers cannot bypass
    // end_at / max_runs limits — the schedule has reached its terminal state.
    // Also check live bounds: the scheduler may not have processed the row yet
    // (e.g. next_run_at > end_at, or max_runs was tightened mid-flight), so
    // exhausted_at can be NULL even though the bounds are already violated.
    {
        let trigger_now = chrono::Utc::now();
        let live_end_at_exceeded = schedule.end_at.is_some_and(|end| trigger_now >= end);
        let live_budget_exhausted = schedule
            .max_runs
            .is_some_and(|max| max > 0 && schedule.runs_started >= max);
        if schedule.exhausted_at.is_some() || live_end_at_exceeded || live_budget_exhausted {
            if let Ok(mut conn) = acquire_conn(pool.default_pool()).await {
                let ar = NewAuditRecord {
                    actor: &actor,
                    operation: OP_SCHEDULE_TRIGGER,
                    target_type: TARGET_SCHEDULE,
                    target_id: Some(id.as_str()),
                    route_or_command: route,
                    request_id: request_id.as_deref(),
                    idempotency_key: None,
                    status: STATUS_FAILED,
                    error_summary: Some("rejected_exhausted"),
                    shard_id: None,
                    source: &source,
                };
                let _ = audit::insert_audit(&mut conn, &ar).await;
            }
            runtime
                .registry
                .telemetry()
                .metrics
                .record_schedule_manual_trigger(&schedule_display_name, "rejected_exhausted");
            return Err(AutumnError::bad_request_msg(format!(
                "schedule {schedule_id} is exhausted (end_at or max_runs reached)"
            ))
            .with_status(axum::http::StatusCode::CONFLICT));
        }
    }

    // Resolve the effective overlap policy (body override takes precedence).
    let effective_overlap_policy = if let Some(ref op_str) = body.overlap_policy {
        match autumn_harvest::OverlapPolicy::from_user_input(op_str) {
            Ok(op) => op,
            Err(e) => {
                return Err(AutumnError::bad_request_msg(format!(
                    "invalid overlap_policy: {e}"
                )));
            }
        }
    } else {
        autumn_harvest::OverlapPolicy::from_db(&schedule.overlap_policy)
    };

    // Determine workflow name, input, and queue from the schedule.
    let (workflow_name, input, queue_name) = match (
        schedule.workflow_name.as_deref(),
        schedule.dag_name.as_deref(),
    ) {
        (Some(wf_name), _) => {
            let input = schedule
                .workflow_input
                .clone()
                .unwrap_or(serde_json::Value::Null);
            let queue = schedule
                .queue_name
                .as_deref()
                .unwrap_or("default")
                .to_string();
            (wf_name.to_string(), input, queue)
        }
        (None, Some(dag_name)) => {
            let dag_queue = runtime
                .dags()
                .get(dag_name)
                .and_then(|d| d.default_queue.as_deref())
                .or(schedule.queue_name.as_deref())
                .unwrap_or("default")
                .to_string();
            (dag_name.to_string(), serde_json::Value::Null, dag_queue)
        }
        (None, None) => {
            return Err(AutumnError::service_unavailable_msg(
                "schedule row has neither workflow_name nor dag_name",
            ));
        }
    };

    // Pre-generate triggered_at and workflow_id so the gate check uses the
    // actual execution shard (router-determined) rather than a hard-coded 0.
    let triggered_at = chrono::Utc::now();
    // Append a UUID v4 so concurrent trigger calls within the same millisecond
    // each produce a distinct workflow_id and start independent executions.
    let workflow_id = format!(
        "manual-{schedule_id}-{}-{}",
        triggered_at.timestamp_millis(),
        uuid::Uuid::new_v4().simple()
    );
    let trigger_exec_shard = if schedule.dag_name.is_some() {
        // DAG runs are pinned to a shard by dag_name (stable rendezvous hash on
        // the name alone), mirroring `scheduler.rs` and `GET /dags/{name}/runs`.
        // Using pick_for_new_workflow with a random workflow_id would produce a
        // different shard and make the manual run invisible to the DAG runs list.
        runtime.router.pick_for_dag(&workflow_name)
    } else {
        runtime
            .router
            .pick_for_new_workflow(&workflow_name, &workflow_id)
    };

    // issue #377: check admission gates before firing a manual trigger.
    {
        let dag_lookup_key = schedule.dag_name.as_deref().unwrap_or(&workflow_name);
        let wf_owner = runtime
            .registry
            .workflows
            .get(&workflow_name)
            .and_then(|i| i.owner)
            .or_else(|| {
                runtime
                    .dags()
                    .get(dag_lookup_key)
                    .and_then(|d| d.owner.as_deref())
            });
        let gate_hit = api_state.gate_cache().check(
            &workflow_name,
            &queue_name,
            trigger_exec_shard.as_i32(),
            wf_owner,
        );
        if let Some((gate_id, gate_reason, scope_kind)) = gate_hit {
            let reason_label = match gate_reason.char_indices().nth(64) {
                Some((idx, _)) => &gate_reason[..idx],
                None => &gate_reason,
            };
            runtime
                .registry
                .telemetry()
                .metrics
                .record_admission_blocked(scope_kind, reason_label);
            if let Ok(mut conn) = acquire_conn(pool.default_pool()).await {
                let err_str = format!("admission blocked by gate {gate_id}: {gate_reason}");
                let ar = NewAuditRecord {
                    actor: &actor,
                    operation: OP_SCHEDULE_TRIGGER,
                    target_type: TARGET_SCHEDULE,
                    target_id: Some(id.as_str()),
                    route_or_command: route,
                    request_id: request_id.as_deref(),
                    idempotency_key: None,
                    status: STATUS_FAILED,
                    error_summary: Some(err_str.as_str()),
                    shard_id: None,
                    source: &source,
                };
                let _ = audit::insert_audit(&mut conn, &ar).await;
            }
            return Err(AutumnError::service_unavailable_msg(format!(
                "admission blocked by gate {gate_id}: {gate_reason}"
            )));
        }
    }

    // triggered_at and workflow_id were pre-generated above for the gate check.

    // Acquire the DB connection early so it is available for both the overlap-skip
    // audit record and the normal start call.
    let mut conn = acquire_conn(pool.default_pool()).await?;
    // Acquire a separate connection on the schedule's own shard for budget accounting.
    // Schedule rows for unified-DAG schedules may live on a non-default shard; using
    // pool.default_pool() here would target zero rows (issue #478).
    let sched_pool = pool.pool_for(schedule_shard);
    let mut sched_conn = acquire_conn(sched_pool).await?;
    // Acquire a connection on the execution shard so the start call lands on the
    // correct Postgres database (trigger_exec_shard was resolved above via the
    // ShardRouter — using pool.default_pool() here would silently misroute in
    // multi-shard deployments).
    let mut exec_conn = acquire_conn(pool.pool_for(trigger_exec_shard)).await?;

    // For Skip policy, fail closed: if the running-count query fails on any shard,
    // treat it as saturated rather than silently firing through.
    if effective_overlap_policy == autumn_harvest::OverlapPolicy::Skip {
        let is_saturated =
            match query_running_count(&pool, &ScheduleKind::Workflow, &workflow_name, schedule.id)
                .await
            {
                Ok(running) => running >= i64::from(schedule.max_active_runs),
                Err(_) => true,
            };
        if is_saturated {
            let ar = NewAuditRecord {
                actor: &actor,
                operation: OP_SCHEDULE_TRIGGER,
                target_type: TARGET_SCHEDULE,
                target_id: Some(id.as_str()),
                route_or_command: route,
                request_id: request_id.as_deref(),
                idempotency_key: None,
                status: STATUS_SUCCEEDED,
                error_summary: Some("skipped_overlap"),
                shard_id: None,
                source: &source,
            };
            let _ = audit::insert_audit(&mut conn, &ar).await;
            runtime
                .registry
                .telemetry()
                .metrics
                .record_schedule_manual_trigger(&schedule_display_name, "skipped_overlap");
            return Ok(Json(ScheduleTriggerResponse {
                execution_id: None,
                workflow_id,
                triggered_at,
                outcome: "skipped_overlap".to_string(),
            }));
        }
    }

    // Atomically reserve one run slot against the max_runs budget before starting
    // the workflow (issue #478). The WHERE guard prevents concurrent manual triggers
    // from racing past the earlier in-memory admission check: only one of them
    // increments successfully when runs_started is at the limit.
    //
    // For unlimited schedules (max_runs IS NULL) the WHERE always matches, so
    // runs_started is incremented for observability and rows_affected = 1.
    //
    // If rows_affected = 0, either exhausted_at was set by a concurrent scheduler
    // tick/trigger between our admission check and this point, or a concurrent
    // trigger already consumed the last slot.
    {
        use autumn_harvest::schema::harvest_schedules::dsl as sdsl;
        let reserved = diesel::update(
            sdsl::harvest_schedules
                .find(schedule.id)
                .filter(sdsl::exhausted_at.is_null())
                .filter(diesel::dsl::sql::<diesel::sql_types::Bool>(
                    "max_runs IS NULL OR runs_started < max_runs",
                )),
        )
        .set((
            sdsl::runs_started.eq(sdsl::runs_started + 1),
            sdsl::updated_at.eq(triggered_at),
        ))
        .execute(&mut sched_conn)
        .await
        .map_err(database_error)
        .map_err(map_error)?;
        if reserved == 0 {
            runtime
                .registry
                .telemetry()
                .metrics
                .record_schedule_manual_trigger(&schedule_display_name, "rejected_exhausted");
            return Err(AutumnError::bad_request_msg(format!(
                "schedule {schedule_id} run budget exhausted (concurrent trigger or tick)"
            ))
            .with_status(axum::http::StatusCode::CONFLICT));
        }
    }

    let exec_id = ExecutionId::new_for_shard(trigger_exec_shard);

    let (owner, runbook_url, severity) = {
        let wf_meta = runtime
            .registry
            .workflows
            .get(&workflow_name)
            .map(|info| (info.owner, info.runbook_url, info.severity));
        let dag_meta = runtime.dags().get(&workflow_name).map(|dag| {
            (
                dag.owner.as_deref(),
                dag.runbook_url.as_deref(),
                dag.severity.as_deref(),
            )
        });
        match (wf_meta, dag_meta) {
            (Some((o, r, s)), Some((dag_owner, dag_runbook, dag_severity))) => {
                (o.or(dag_owner), r.or(dag_runbook), s.or(dag_severity))
            }
            (Some((o, r, s)), None) => (o, r, s),
            (None, Some((dag_owner, dag_runbook, dag_severity))) => {
                (dag_owner, dag_runbook, dag_severity)
            }
            (None, None) => (None, None, None),
        }
    };
    // Only registered workflows carry an SLA default; DAGs have no SLA concept.
    let sla = runtime
        .registry
        .workflows
        .get(&workflow_name)
        .and_then(|info| clamp_info_default_sla(info.sla, info.execution_timeout));
    let info_execution_timeout = runtime
        .registry
        .workflows
        .get(&workflow_name)
        .and_then(|info| info.execution_timeout)
        .and_then(|d| chrono::Duration::from_std(d).ok());
    // Chain-scoped lifetime cap default (issue #617): only registered workflows
    // carry it; DAGs have no chain-cap concept.
    let info_chain_execution_timeout = runtime
        .registry
        .workflows
        .get(&workflow_name)
        .and_then(|info| info.chain_execution_timeout)
        .and_then(|d| chrono::Duration::from_std(d).ok());
    let (concurrency_key, concurrency_limit, concurrency_on_conflict) = runtime
        .registry
        .workflows
        .get(&workflow_name)
        .and_then(|info| info.concurrency.as_ref())
        .map_or(
            (
                None,
                None,
                autumn_harvest::concurrency::ConcurrencyOnConflict::Defer,
            ),
            |policy| {
                let key =
                    autumn_harvest::concurrency::resolve_concurrency_key(policy.key_expr, &input);
                (key, Some(policy.limit), policy.on_conflict)
            },
        );
    // Schedule-level retry_policy takes precedence over the workflow-type default,
    // mirroring the automated tick and backfill paths (scheduler.rs).
    let manual_trigger_retry_policy = schedule
        .retry_policy
        .as_ref()
        .and_then(|v| serde_json::from_value(v.clone()).ok())
        .or_else(|| {
            runtime
                .registry
                .workflows
                .get(&workflow_name)
                .and_then(|info| info.retry_policy.clone())
        });

    // Start-throttle admission (issue #607 code review): a manual trigger-now
    // must pace like scheduled/backfilled fires rather than always admitting
    // immediately -- otherwise an operator repeatedly hitting this route
    // could bypass a throttled workflow's declared rate/burst entirely. DAG
    // schedules resolve no throttle policy here (`DagInfo` has no `throttle`
    // field, and a unified DAG's auto-registered shadow `WorkflowInfo` never
    // carries one either), so this is a no-op for the DAG branch by
    // construction -- unlike `schedule_backfill`, no explicit kind check is
    // needed. A deferred trigger still counts as a spent run-budget slot
    // (mirrors the scheduler-tick/backfill precedent: the pre-incremented
    // `runs_started` above is NOT rolled back), so a repeatedly-triggered
    // throttled schedule can't also bypass its own `max_runs` budget by
    // piling up pending rows.
    let mut trigger_throttle_bucket: Option<String> = None;
    if let Some((throttle_policy, resolved_throttle_key)) =
        workflow_resolving_throttle(&runtime.registry, &workflow_name, &input)
    {
        let effective_cap = runtime
            .registry
            .workflows
            .get(&workflow_name)
            .and_then(|info| info.max_input_bytes)
            .map_or(runtime.registry.max_workflow_input_bytes, |per| {
                per.max(runtime.registry.max_workflow_input_bytes)
            });
        // Mirrors the size-check-ordering fix applied at every other call
        // site (issue #607 round 4): skip the cap check when
        // `reserve_or_defer` would resolve via `Bypassed` or an idempotent
        // attach to an already-pending row. `workflow_id` here is always
        // freshly generated per request, so this is mostly defensive, but
        // keeps the primitive's contract uniform across every call site.
        let skip_cap_check = match autumn_harvest::throttle::skip_size_check(
            &mut exec_conn,
            &workflow_name,
            &workflow_id,
            Some("allow_duplicate"),
        )
        .await
        {
            Ok(skip) => skip,
            Err(e) => {
                rollback_manual_trigger_budget(&mut sched_conn, schedule.id, triggered_at).await;
                let ar = NewAuditRecord {
                    actor: &actor,
                    operation: OP_SCHEDULE_TRIGGER,
                    target_type: TARGET_SCHEDULE,
                    target_id: Some(id.as_str()),
                    route_or_command: route,
                    request_id: request_id.as_deref(),
                    idempotency_key: None,
                    status: STATUS_FAILED,
                    error_summary: Some("throttle_admission_failed"),
                    shard_id: None,
                    source: &source,
                };
                let _ = audit::insert_audit(&mut conn, &ar).await;
                runtime
                    .registry
                    .telemetry()
                    .metrics
                    .record_schedule_manual_trigger(&schedule_display_name, "start_failed");
                return Err(map_error(e));
            }
        };
        if !skip_cap_check && effective_cap > 0 {
            let observed = serde_json::to_string(&input).map_or(0u64, |s| s.len() as u64);
            if observed > effective_cap {
                rollback_manual_trigger_budget(&mut sched_conn, schedule.id, triggered_at).await;
                let ar = NewAuditRecord {
                    actor: &actor,
                    operation: OP_SCHEDULE_TRIGGER,
                    target_type: TARGET_SCHEDULE,
                    target_id: Some(id.as_str()),
                    route_or_command: route,
                    request_id: request_id.as_deref(),
                    idempotency_key: None,
                    status: STATUS_FAILED,
                    error_summary: Some("rejected_oversized_input"),
                    shard_id: None,
                    source: &source,
                };
                let _ = audit::insert_audit(&mut conn, &ar).await;
                runtime
                    .registry
                    .telemetry()
                    .metrics
                    .record_schedule_manual_trigger(
                        &schedule_display_name,
                        "rejected_oversized_input",
                    );
                return Err(AutumnError::bad_request_msg(format!(
                    "workflow input ({observed} bytes) exceeds cap ({effective_cap} bytes)"
                )));
            }
        }
        let start_options = autumn_harvest::debounce::DebounceStartOptions {
            reuse_policy: Some("allow_duplicate".to_string()),
            execution_timeout_secs: info_execution_timeout.map(|d| d.num_seconds()),
            memo: None,
            search_attrs: None,
            sla_secs: sla.map(|d| d.num_seconds()),
            context_headers: None,
            priority: None,
            concurrency_key: concurrency_key.clone(),
            concurrency_limit,
            concurrency_on_conflict: Some(concurrency_on_conflict),
            owner: owner.map(str::to_string),
            runbook_url: runbook_url.map(str::to_string),
            severity: severity.map(str::to_string),
            max_execution_timeout_ceiling_secs: api_state
                .max_workflow_execution_timeout()
                .map(|d| i64::try_from(d.as_secs()).unwrap_or(i64::MAX)),
            // Chain-scoped lifetime cap (issue #617): workflow-type default +
            // fleet-wide ceiling captured so a throttled manual-trigger fire keeps
            // the cap.
            chain_execution_timeout_secs: info_chain_execution_timeout.map(|d| d.num_seconds()),
            max_workflow_chain_timeout_ceiling_secs: api_state
                .max_workflow_chain_timeout()
                .map(|d| i64::try_from(d.as_secs()).unwrap_or(i64::MAX)),
            max_workflow_input_bytes: Some(effective_cap),
            trace_context: None,
            workflow_retry_policy: manual_trigger_retry_policy
                .as_ref()
                .and_then(|p| serde_json::to_value(p).ok()),
            max_workflow_attempts_ceiling: api_state.max_workflow_attempts(),
            completion_callbacks: None,
            schedule_id: Some(schedule_id),
            scheduled_for: None,
            origin: Some(autumn_harvest::execution::ORIGIN_MANUAL_TRIGGER.to_string()),
            // Manual trigger-now (issue #740): provenance is `schedule`,
            // referencing the schedule id, attributed to the operator.
            start_source: Some(autumn_harvest::StartSource::Schedule.as_str().to_string()),
            start_source_ref: Some(schedule_id.to_string()),
            started_by: Some(actor.clone()),
        };
        match autumn_harvest::throttle::reserve_or_defer(
            &mut exec_conn,
            autumn_harvest::throttle::AdmitThrottleParams {
                workflow_name: &workflow_name,
                throttle_key: &resolved_throttle_key,
                workflow_id: &workflow_id,
                queue_name: &queue_name,
                input: input.clone(),
                start_options,
                refill_per_sec: throttle_policy.refill_per_sec,
                burst: throttle_policy.burst,
                schedule_to_start: throttle_policy.schedule_to_start,
                shard_id: trigger_exec_shard.as_i32(),
            },
        )
        .await
        {
            Ok(autumn_harvest::throttle::ThrottleAdmission::Deferred(_)) => {
                runtime
                    .registry
                    .telemetry()
                    .metrics
                    .record_start_throttled(&workflow_name);
                let ar = NewAuditRecord {
                    actor: &actor,
                    operation: OP_SCHEDULE_TRIGGER,
                    target_type: TARGET_SCHEDULE,
                    target_id: Some(id.as_str()),
                    route_or_command: route,
                    request_id: request_id.as_deref(),
                    idempotency_key: None,
                    status: STATUS_SUCCEEDED,
                    error_summary: Some("deferred"),
                    shard_id: None,
                    source: &source,
                };
                let _ = audit::insert_audit(&mut conn, &ar).await;
                // The pre-increment above already wrote runs_started =
                // runs_started + 1. If that new value reaches max_runs,
                // transition to exhausted now, exactly like the "fired"
                // success path below -- a deferred fire still spends budget.
                {
                    use autumn_harvest::schema::harvest_schedules::dsl as sdsl;
                    let new_runs_started = schedule.runs_started.saturating_add(1);
                    if schedule
                        .max_runs
                        .is_some_and(|max| max > 0 && new_runs_started >= max)
                    {
                        let _ = diesel::update(
                            sdsl::harvest_schedules
                                .find(schedule.id)
                                .filter(sdsl::exhausted_at.is_null()),
                        )
                        .set((
                            sdsl::exhausted_at.eq(Some(triggered_at)),
                            sdsl::exhausted_reason.eq(Some("max_runs_exhausted")),
                            sdsl::next_run_at.eq(None::<chrono::DateTime<chrono::Utc>>),
                            sdsl::updated_at.eq(triggered_at),
                        ))
                        .execute(&mut sched_conn)
                        .await;
                    }
                }
                runtime
                    .registry
                    .telemetry()
                    .metrics
                    .record_schedule_manual_trigger(&schedule_display_name, "deferred");
                return Ok(Json(ScheduleTriggerResponse {
                    execution_id: None,
                    workflow_id,
                    triggered_at,
                    outcome: "deferred".to_string(),
                }));
            }
            Ok(autumn_harvest::throttle::ThrottleAdmission::Reserved { bucket_key }) => {
                trigger_throttle_bucket = Some(bucket_key);
            }
            Ok(autumn_harvest::throttle::ThrottleAdmission::Bypassed) => {
                // Active execution already resolves this reuse policy as a
                // no-op; no token reserved, fall through to the normal start.
            }
            Err(e) => {
                rollback_manual_trigger_budget(&mut sched_conn, schedule.id, triggered_at).await;
                let ar = NewAuditRecord {
                    actor: &actor,
                    operation: OP_SCHEDULE_TRIGGER,
                    target_type: TARGET_SCHEDULE,
                    target_id: Some(id.as_str()),
                    route_or_command: route,
                    request_id: request_id.as_deref(),
                    idempotency_key: None,
                    status: STATUS_FAILED,
                    error_summary: Some("throttle_admission_failed"),
                    shard_id: None,
                    source: &source,
                };
                let _ = audit::insert_audit(&mut conn, &ar).await;
                runtime
                    .registry
                    .telemetry()
                    .metrics
                    .record_schedule_manual_trigger(&schedule_display_name, "start_failed");
                return Err(map_error(e));
            }
        }
    }

    // issue #740: manual trigger-now provenance is `schedule`, referencing the
    // schedule id and attributed to the operator (mirrors the throttle-carrier
    // branch above). Bound in the enclosing scope so the ref outlives the params.
    let manual_schedule_id_str = schedule_id.to_string();
    let result = start_or_load_workflow_execution_with_metrics_and_codecs(
        &mut exec_conn,
        StartWorkflowParams {
            workflow_name: &workflow_name,
            workflow_id: &workflow_id,
            exec_id,
            input: input.clone(),
            parent_id: None,
            queue_name: &queue_name,
            execution_timeout: info_execution_timeout,
            memo: None,
            search_attrs: None,
            reuse_policy: WorkflowIdReusePolicy::AllowDuplicate,
            conflict_policy: autumn_harvest::types::WorkflowIdConflictPolicy::Unspecified,
            trace_context: None,
            max_execution_timeout_ceiling: api_state
                .max_workflow_execution_timeout()
                .map(|d| chrono::Duration::from_std(d).unwrap_or(chrono::Duration::MAX)),
            // Chain-scoped lifetime cap (issue #617): workflow-type default +
            // fleet-wide ceiling-as-default, at parity with the per-run timeout.
            chain_execution_timeout: info_chain_execution_timeout,
            max_workflow_chain_timeout_ceiling: api_state
                .max_workflow_chain_timeout()
                .map(|d| chrono::Duration::from_std(d).unwrap_or(chrono::Duration::MAX)),
            inherited_chain_deadline_at: None,
            concurrency_key,
            concurrency_limit,
            concurrency_on_conflict,
            priority: Priority::default(),
            max_workflow_input_bytes: runtime
                .registry
                .workflows
                .get(&workflow_name)
                .and_then(|info| info.max_input_bytes)
                .map_or(runtime.registry.max_workflow_input_bytes, |per| {
                    per.max(runtime.registry.max_workflow_input_bytes)
                }),
            start_at: None,
            delay: None,
            max_workflow_start_delay: None,
            owner,
            runbook_url,
            severity,
            context_headers: None,
            sla,
            // Manual trigger-now is *attributed* to its schedule (issue #534) so it shows
            // up in GET /admin/schedules/{id}/runs, but is marked origin=manual_trigger so
            // it never masquerades as normal cadence. It deliberately does NOT participate
            // in scheduled carryover (issue #488): scheduled_for stays None, so
            // resolve_carryover short-circuits to (None, None) before any DB query (it never
            // runs the cross-shard carryover lookup on this default-pool connection). The UI
            // trigger path also lacks the budget/exhaustion checks the automated lineage
            // relies on — only scheduled fires and backfills advance the carryover cursor.
            schedule_id: Some(schedule_id),
            scheduled_for: None,
            workflow_attempt: 1,
            workflow_retry_policy: manual_trigger_retry_policy,
            retry_of_exec_id: None,
            max_workflow_attempts_ceiling: api_state.max_workflow_attempts(),
            origin: Some(autumn_harvest::execution::ORIGIN_MANUAL_TRIGGER),
            completion_callbacks: None,
            start_source: autumn_harvest::StartSource::Schedule,
            start_source_ref: Some(manual_schedule_id_str.as_str()),
            started_by: Some(actor.as_str()),
        },
        Some(runtime.registry.telemetry().metrics.as_ref()),
        None,
        runtime.registry.payload_codecs(),
    )
    .await;

    let (exec_id_out, outcome) = match result {
        Ok(exec_result) => {
            // AC-a (issue #607): an id-reuse short-circuit that attached to an
            // existing run instead of creating one must refund its reserved
            // token, mirroring every other admission call site.
            if !exec_result.created
                && let Some(ref bucket) = trigger_throttle_bucket
            {
                let _ =
                    autumn_harvest::queue::refund_rate_limit_token(&mut exec_conn, bucket).await;
            }
            (Some(exec_result.exec_id.as_uuid()), "fired")
        }
        Err(e) => {
            // Undo the pre-increment so the budget reflects actual started workflows.
            rollback_manual_trigger_budget(&mut sched_conn, schedule.id, triggered_at).await;
            // Refund the reserved throttle token too (code review, issue #607):
            // a failed start never admitted anything, so leaving the token
            // spent would drain the bucket for every repeated transient/
            // configuration failure, artificially deferring later manual or
            // scheduled fires behind a bucket that never actually paced a
            // successful start.
            if let Some(ref bucket) = trigger_throttle_bucket {
                let _ =
                    autumn_harvest::queue::refund_rate_limit_token(&mut exec_conn, bucket).await;
            }
            let ar = NewAuditRecord {
                actor: &actor,
                operation: OP_SCHEDULE_TRIGGER,
                target_type: TARGET_SCHEDULE,
                target_id: Some(id.as_str()),
                route_or_command: route,
                request_id: request_id.as_deref(),
                idempotency_key: None,
                status: STATUS_FAILED,
                error_summary: Some("start_failed"),
                shard_id: None,
                source: &source,
            };
            let _ = audit::insert_audit(&mut conn, &ar).await;
            runtime
                .registry
                .telemetry()
                .metrics
                .record_schedule_manual_trigger(&schedule_display_name, "start_failed");
            return Err(map_error(e));
        }
    };

    let ar = NewAuditRecord {
        actor: &actor,
        operation: OP_SCHEDULE_TRIGGER,
        target_type: TARGET_SCHEDULE,
        target_id: Some(id.as_str()),
        route_or_command: route,
        request_id: request_id.as_deref(),
        idempotency_key: None,
        status: STATUS_SUCCEEDED,
        error_summary: body.reason.as_deref(),
        shard_id: None,
        source: &source,
    };
    audit::insert_audit(&mut conn, &ar)
        .await
        .map_err(map_error)?;

    // The pre-increment above already wrote runs_started = runs_started + 1.
    // If that new value reaches max_runs, transition to exhausted now so the
    // schedule immediately disappears from the due-list. The guard on
    // exhausted_at IS NULL prevents a double-exhaustion race with the tick.
    {
        use autumn_harvest::schema::harvest_schedules::dsl as sdsl;
        let new_runs_started = schedule.runs_started.saturating_add(1);
        if schedule
            .max_runs
            .is_some_and(|max| max > 0 && new_runs_started >= max)
        {
            let _ = diesel::update(
                sdsl::harvest_schedules
                    .find(schedule.id)
                    .filter(sdsl::exhausted_at.is_null()),
            )
            .set((
                sdsl::exhausted_at.eq(Some(triggered_at)),
                sdsl::exhausted_reason.eq(Some("max_runs_exhausted")),
                sdsl::next_run_at.eq(None::<chrono::DateTime<chrono::Utc>>),
                sdsl::updated_at.eq(triggered_at),
            ))
            .execute(&mut sched_conn)
            .await;
        }
    }

    runtime
        .registry
        .telemetry()
        .metrics
        .record_schedule_manual_trigger(&schedule_display_name, outcome);

    Ok(Json(ScheduleTriggerResponse {
        execution_id: exec_id_out,
        workflow_id,
        triggered_at,
        outcome: outcome.to_string(),
    }))
}

/// Undo `trigger_schedule_now`'s pre-incremented `runs_started` budget slot
/// when the trigger did not end up producing a run — a start failure, or
/// (issue #607) an oversized input / throttle-admission error caught before
/// the start primitive is ever called. Do NOT guard the decrement on
/// `exhausted_at IS NULL`: a scheduler tick could have raced and set
/// `exhausted_at` after the pre-increment, so the guard would silently skip
/// the rollback and leave `runs_started` inflated (issue #478). If the
/// decrement brought `runs_started` below `max_runs`, clear any exhaustion the
/// (now-reversed) pre-increment may have caused; `next_run_at` is
/// intentionally not restored here — a future `upsert_workflow_schedule` call
/// (e.g. on server restart for code-declared schedules) will recalculate it.
async fn rollback_manual_trigger_budget(
    sched_conn: &mut diesel_async::AsyncPgConnection,
    schedule_id: uuid::Uuid,
    at: chrono::DateTime<chrono::Utc>,
) {
    use autumn_harvest::schema::harvest_schedules::dsl as sdsl;
    let _ = diesel::update(sdsl::harvest_schedules.find(schedule_id))
        .set((
            sdsl::runs_started.eq(sdsl::runs_started - 1),
            sdsl::updated_at.eq(at),
        ))
        .execute(sched_conn)
        .await;
    let _ = diesel::update(
        sdsl::harvest_schedules
            .find(schedule_id)
            .filter(sdsl::exhausted_at.is_not_null())
            .filter(
                sdsl::max_runs
                    .is_null()
                    .or(diesel::dsl::sql::<diesel::sql_types::Bool>(
                        "runs_started < max_runs",
                    )),
            ),
    )
    .set((
        sdsl::exhausted_at.eq(None::<chrono::DateTime<chrono::Utc>>),
        sdsl::exhausted_reason.eq(None::<String>),
        sdsl::updated_at.eq(at),
    ))
    .execute(sched_conn)
    .await;
}

/// Build the atomic reservation UPDATE statement for a backfill dispatch
/// (issue #688). A macro rather than a function because diesel's
/// `UpdateStatement` return type (with `.set(..).returning(..)`) is not cleanly
/// nameable and cannot be boxed here; a macro lets the live path
/// (`reserve_backfill_budget_slot`) and the no-DB shape test share one source of
/// truth, so editing the guard, the increment, or the RETURNING clause breaks the
/// shape test rather than silently drifting. The statement increments
/// `runs_started`, guards on `exhausted_at IS NULL` and the `max_runs` budget,
/// and RETURNs the post-increment `runs_started`. A non-positive `max_runs`
/// (`max_runs <= 0`) is treated as UNLIMITED here — matching
/// `transition_backfill_exhausted_stmt!`, the up-front exhaustion check, and the
/// dry-run projection — so a row with `max_runs = 0` never wrongly reserves 0 rows.
macro_rules! reserve_backfill_budget_slot_stmt {
    ($schedule_id:expr, $at:expr) => {{
        use autumn_harvest::schema::harvest_schedules::dsl as sdsl;
        diesel::update(
            sdsl::harvest_schedules
                .find($schedule_id)
                .filter(sdsl::exhausted_at.is_null())
                .filter(diesel::dsl::sql::<diesel::sql_types::Bool>(
                    "max_runs IS NULL OR max_runs <= 0 OR runs_started < max_runs",
                )),
        )
        .set((
            sdsl::runs_started.eq(sdsl::runs_started + 1),
            sdsl::updated_at.eq($at),
        ))
        .returning(sdsl::runs_started)
    }};
}

/// Build the "clear a stale `max_runs_exhausted` exhaustion" UPDATE used by
/// `release_backfill_budget_slot` when a decrement drops `runs_started` back
/// below the cap (issue #688 review, Codex). A macro (like
/// `reserve_backfill_budget_slot_stmt!`) so the live path and the no-DB shape
/// test share one source of truth. Guarded on `exhausted_reason =
/// 'max_runs_exhausted'` so an `end_at` exhaustion set by a concurrent tick is
/// NEVER resurrected, on `exhausted_at IS NOT NULL`, and on the below-cap
/// predicate (with the same `max_runs <= 0` = unlimited handling as the
/// reservation guard). Clears `exhausted_at`/`exhausted_reason` only; does NOT
/// touch `next_run_at` (backfill's own transition no longer nulls it, so it
/// retains the tick's last valid forward pointer).
macro_rules! clear_stale_max_runs_exhaustion_stmt {
    ($schedule_id:expr, $at:expr) => {{
        use autumn_harvest::schema::harvest_schedules::dsl as sdsl;
        diesel::update(
            sdsl::harvest_schedules
                .find($schedule_id)
                .filter(sdsl::exhausted_at.is_not_null())
                .filter(sdsl::exhausted_reason.eq("max_runs_exhausted"))
                .filter(diesel::dsl::sql::<diesel::sql_types::Bool>(
                    "max_runs IS NULL OR max_runs <= 0 OR runs_started < max_runs",
                )),
        )
        .set((
            sdsl::exhausted_at.eq(None::<chrono::DateTime<chrono::Utc>>),
            sdsl::exhausted_reason.eq(None::<String>),
            sdsl::updated_at.eq($at),
        ))
    }};
}

/// Build the "re-arm `next_run_at`" UPDATE used by `release_backfill_budget_slot`
/// (issue #688 review, Codex F3) after the clear above actually un-exhausts a
/// `max_runs_exhausted` row. A scheduler *tick* that exhausts the schedule nulls
/// `next_run_at` (`tick_one_workflow_schedule` in scheduler.rs), and the due-list
/// query requires `next_run_at IS NOT NULL` — so when a concurrent tick exhausts
/// the row DURING a backfill and the backfill then releases below cap, clearing
/// the exhaustion alone would leave the schedule un-exhausted yet off the
/// due-list. This restores the forward pointer to the next slot after now (an
/// approximation the tick later refines with calendar/skip adjustments on its
/// next firing). Guarded on `next_run_at IS NULL` so the common intra-backfill
/// case (where our own transition never nulled it) is a no-op, and on
/// `exhausted_at IS NULL` so we only re-arm a row we just un-exhausted.
macro_rules! rearm_backfill_next_run_stmt {
    ($schedule_id:expr, $next:expr, $at:expr) => {{
        use autumn_harvest::schema::harvest_schedules::dsl as sdsl;
        diesel::update(
            sdsl::harvest_schedules
                .find($schedule_id)
                .filter(sdsl::exhausted_at.is_null())
                .filter(sdsl::next_run_at.is_null()),
        )
        .set((sdsl::next_run_at.eq($next), sdsl::updated_at.eq($at)))
    }};
}

/// Atomically reserve one `max_runs` slot for a backfill dispatch (issue #688),
/// mirroring `trigger_schedule_now`'s pre-increment. Runs on the schedule's own
/// shard. Returns `Ok(Some(new_runs_started))` when a slot was reserved (the
/// post-increment value), `Ok(None)` when the budget is exhausted (0 rows), or a
/// DB error. Unlimited schedules (`max_runs IS NULL`) always reserve and
/// increment for observability, matching the prior post-loop batch increment.
async fn reserve_backfill_budget_slot(
    sched_conn: &mut diesel_async::AsyncPgConnection,
    schedule_id: uuid::Uuid,
    at: chrono::DateTime<chrono::Utc>,
) -> Result<Option<i32>, diesel::result::Error> {
    reserve_backfill_budget_slot_stmt!(schedule_id, at)
        .get_result::<i32>(sched_conn)
        .await
        .optional()
}

/// Release a `max_runs` slot reserved by `reserve_backfill_budget_slot` when the
/// dispatch did not ultimately happen (issue #688). Decrement of `runs_started`,
/// then a *guarded* clear of a `max_runs_exhausted` exhaustion when the decrement
/// drops back below the cap.
///
/// The clear is guarded on `exhausted_reason = 'max_runs_exhausted'` so an
/// `end_at` exhaustion set by a concurrent tick is NEVER resurrected — unlike a
/// blanket clear, which could revive a *foreign* exhaustion. It targets the case
/// where two concurrent near-cap backfill reservations both increment
/// `runs_started`, one transitions the row to `max_runs_exhausted` on the
/// temporary count, and the other's slot then releases (`AlreadyExists` /
/// oversized input / admission error) back below the cap — without this, the
/// decrement-only release would leave the schedule stuck exhausted with a free
/// slot. Neither UPDATE touches `next_run_at`: `transition_backfill_exhausted_if_reached`
/// no longer nulls it (Fix 2a), so the row retains the tick's last valid forward
/// pointer and returns to the due-list correctly once un-exhausted.
///
/// Conservative by design: at worst a released slot leaves the schedule marked
/// exhausted with a spare slot (never an over-run). All UPDATEs are best-effort
/// and warn on error so a leaked `+1` or a stale exhaustion is diagnosable rather
/// than silently drifting.
///
/// `rearm_next` (issue #688 review, Codex F3/F5): when the clear above actually
/// un-exhausts a `max_runs_exhausted` row that a concurrent scheduler *tick*
/// nulled `next_run_at` on while exhausting it mid-backfill, re-arm the forward
/// pointer so the schedule returns to the due-list rather than being stranded
/// off it until an unrelated PATCH/restart. `rearm_next` is the pre-tick due
/// `next_run_at` snapshot loaded at backfill request start — NOT a recompute from
/// the release's timestamp (`None` for a manual schedule with no due slot → no
/// re-arm). Recomputing from `now` would advance PAST an already-due slot the tick
/// skipped, dropping that run for a catchup schedule; the snapshot restores the
/// exact slot to retry, which the tick refines with calendar/skip on its next
/// firing. Guarded (see `rearm_backfill_next_run_stmt!`) so the common
/// intra-backfill case (our own transition never nulls `next_run_at`) is a no-op.
async fn release_backfill_budget_slot(
    sched_conn: &mut diesel_async::AsyncPgConnection,
    schedule_id: uuid::Uuid,
    at: chrono::DateTime<chrono::Utc>,
    rearm_next: Option<chrono::DateTime<chrono::Utc>>,
) {
    use autumn_harvest::schema::harvest_schedules::dsl as sdsl;
    if let Err(e) = diesel::update(sdsl::harvest_schedules.find(schedule_id))
        .set((
            sdsl::runs_started.eq(sdsl::runs_started - 1),
            sdsl::updated_at.eq(at),
        ))
        .execute(sched_conn)
        .await
    {
        tracing::warn!(
            schedule_id = %schedule_id,
            error = %e,
            "issue #688: failed to release a reserved backfill max_runs slot; runs_started may be transiently inflated"
        );
    }
    // If the decrement dropped runs_started back below the cap, clear a
    // max_runs exhaustion the row may have picked up from a *concurrent* near-cap
    // backfill reservation's transition (issue #688 review, Codex). Guarded so an
    // end_at exhaustion is never resurrected.
    match clear_stale_max_runs_exhaustion_stmt!(schedule_id, at)
        .execute(sched_conn)
        .await
    {
        Ok(cleared_rows) => {
            // Only when we ACTUALLY un-exhausted a max_runs exhaustion (F3): a
            // concurrent tick that exhausted+nulled next_run_at mid-backfill would
            // otherwise leave the un-exhausted schedule off the due-list. Re-arm
            // the forward pointer (guarded on next_run_at IS NULL so the common
            // case where our own transition never nulled it is a no-op).
            if cleared_rows > 0
                && let Some(next) = rearm_next
                && let Err(e) = rearm_backfill_next_run_stmt!(schedule_id, next, at)
                    .execute(sched_conn)
                    .await
            {
                tracing::warn!(
                    schedule_id = %schedule_id,
                    error = %e,
                    "issue #688: failed to re-arm next_run_at after clearing a tick-nulled max_runs exhaustion"
                );
            }
        }
        Err(e) => {
            tracing::warn!(
                schedule_id = %schedule_id,
                error = %e,
                "issue #688: failed to clear stale max_runs exhaustion on backfill budget release"
            );
        }
    }
}

/// Build the "transition a backfill schedule to exhausted" UPDATE (issue #688,
/// Codex F6). A macro (like `reserve_backfill_budget_slot_stmt!` /
/// `clear_stale_max_runs_exhaustion_stmt!` / `rearm_backfill_next_run_stmt!`) so
/// the live path (`transition_backfill_exhausted_if_reached`) and the no-DB shape
/// test share one source of truth. The WHERE clause reads `max_runs`/`runs_started`
/// FROM THE ROW ITSELF (`max_runs IS NOT NULL AND max_runs > 0 AND runs_started >=
/// max_runs`) rather than a request-start snapshot, so it always matches the same
/// live row the reservation UPDATE already evaluated. That makes exhaustion
/// race-safe against a concurrent `PATCH /admin/schedules/{id}` (issue #771) that
/// changes `max_runs` between the reservation and this call: a raised/removed cap
/// no longer wrongly exhausts, and a lowered cap correctly exhausts an at-cap row.
/// `max_runs <= 0`/NULL are UNLIMITED (never exhaust), matching the reservation
/// guard. Guarded on `exhausted_at IS NULL` (no double-exhaust race with the tick);
/// `next_run_at` is deliberately NOT touched (backfill dispatches historical slots
/// and does not own the forward-cadence pointer — that is the scheduler tick's job;
/// the `exhausted_at IS NULL` due-list filter already excludes an exhausted row, and
/// nulling it would strand the schedule off the due-list if the exhaustion is later
/// cleared by `release_backfill_budget_slot` dropping below cap).
macro_rules! transition_backfill_exhausted_stmt {
    ($schedule_id:expr, $at:expr) => {{
        use autumn_harvest::schema::harvest_schedules::dsl as sdsl;
        diesel::update(
            sdsl::harvest_schedules
                .find($schedule_id)
                .filter(sdsl::exhausted_at.is_null())
                .filter(diesel::dsl::sql::<diesel::sql_types::Bool>(
                    "max_runs IS NOT NULL AND max_runs > 0 AND runs_started >= max_runs",
                )),
        )
        .set((
            sdsl::exhausted_at.eq(Some($at)),
            sdsl::exhausted_reason.eq(Some("max_runs_exhausted")),
            sdsl::updated_at.eq($at),
        ))
    }};
}

/// After a successful `reserve_backfill_budget_slot`, transition the schedule to
/// exhausted iff the LIVE row is at/over its LIVE `max_runs` cap (issue #688,
/// Codex F6). Evaluating `max_runs` and `runs_started` from the row inside the
/// UPDATE — rather than a request-start snapshot — makes this race-safe against a
/// concurrent `PATCH /admin/schedules/{id}` (issue #771) that changes `max_runs`
/// between the reservation and this call; the reservation UPDATE already used live
/// row values, so both budget decisions are now snapshot-free. Best-effort but
/// visible: a failed transition is self-healing (the next tick/backfill re-detects
/// `runs_started >= max_runs`), yet the failure should be diagnosable rather than
/// silent (issue #688).
async fn transition_backfill_exhausted_if_reached(
    sched_conn: &mut diesel_async::AsyncPgConnection,
    schedule_id: uuid::Uuid,
    at: chrono::DateTime<chrono::Utc>,
) {
    if let Err(e) = transition_backfill_exhausted_stmt!(schedule_id, at)
        .execute(sched_conn)
        .await
    {
        tracing::warn!(
            schedule_id = %schedule_id,
            error = %e,
            "issue #688: failed to transition backfill-exhausted schedule to exhausted; next tick/backfill will re-detect"
        );
    }
}

// ── Schedule backfill (issue #177) ────────────────────────────────────────────

/// Request body for `POST /admin/schedules/{id}/backfill`.
#[derive(Debug, Deserialize)]
pub(crate) struct ScheduleBackfillRequest {
    pub from: chrono::DateTime<chrono::Utc>,
    pub to: chrono::DateTime<chrono::Utc>,
    #[serde(default)]
    pub dry_run: bool,
    #[serde(default)]
    pub include_paused: bool,
    pub max_count: Option<usize>,
}

/// A shard that could not be reached or dispatched during a backfill.
#[derive(Debug, Serialize)]
pub(crate) struct BackfillShardFailure {
    pub shard_id: i32,
    pub reason: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum BackfillPriorPrecheck {
    NoPriorRun,
    PriorRunExists,
    PrecheckFailed(String),
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum BackfillRunningCountCheck {
    Count(i64),
    CountFailed(String),
}

fn classify_backfill_prior_count(result: diesel::QueryResult<i64>) -> BackfillPriorPrecheck {
    match result {
        Ok(count) if count > 0 => BackfillPriorPrecheck::PriorRunExists,
        Ok(_) => BackfillPriorPrecheck::NoPriorRun,
        Err(error) => BackfillPriorPrecheck::PrecheckFailed(error.to_string()),
    }
}

fn classify_backfill_running_count(result: diesel::QueryResult<i64>) -> BackfillRunningCountCheck {
    match result {
        Ok(count) => BackfillRunningCountCheck::Count(count),
        Err(error) => BackfillRunningCountCheck::CountFailed(error.to_string()),
    }
}

/// Response for `POST /admin/schedules/{id}/backfill`.
#[derive(Debug, Serialize)]
pub(crate) struct ScheduleBackfillResponse {
    /// `"dry_run"`, `"complete"`, or `"partial"`.
    pub status: String,
    pub schedule_id: uuid::Uuid,
    pub kind: ScheduleKind,
    pub name: String,
    pub from: chrono::DateTime<chrono::Utc>,
    pub to: chrono::DateTime<chrono::Utc>,
    pub planned_timestamps: Vec<chrono::DateTime<chrono::Utc>>,
    pub total: usize,
    pub dispatched: usize,
    pub skipped: usize,
    pub failed: usize,
    /// Machine-readable breakdown of why timestamps were skipped.
    /// Keys: `"already_exists"`, `"max_active_runs"`.
    pub skipped_reasons: std::collections::HashMap<String, usize>,
    pub partial_shard_failures: Vec<BackfillShardFailure>,
    /// Set when a DAG schedule is paused and `include_paused=true`: inserted
    /// QUEUED runs will not execute until the schedule is resumed because
    /// `activate_queued_runs` skips paused schedules.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub paused_schedule_warning: Option<String>,
}

async fn schedule_backfill(
    Extension(api_state): Extension<HarvestApiState>,
    Path(id): Path<String>,
    headers: axum::http::HeaderMap,
    Json(request): Json<ScheduleBackfillRequest>,
) -> Result<Json<ScheduleBackfillResponse>, AutumnError> {
    schedule_backfill_inner(
        &api_state,
        &id,
        &headers,
        request,
        "POST /admin/schedules/{id}/backfill",
    )
    .await
    .map(Json)
}

/// The backfill implementation, with the audited `route_or_command` supplied by
/// the caller.
///
/// The Vantage backfill launcher (issue #951) shares this body so it inherits
/// every guard, the `harvest_backfill_log` row and the audit record — but it
/// passes its **own** route string, so a dashboard-initiated backfill is
/// recorded as `POST /ui/schedules/{id}/backfill` rather than masquerading as an
/// API call. Mirrors how `retry_dag_run_inner` is shared with `dag_retry_commit_ui`.
///
/// # Errors
///
/// Propagates the same errors as `POST /admin/schedules/{id}/backfill`.
#[allow(clippy::too_many_lines)]
pub(crate) async fn schedule_backfill_inner(
    api_state: &HarvestApiState,
    id: &str,
    headers: &axum::http::HeaderMap,
    request: ScheduleBackfillRequest,
    route: &str,
) -> Result<ScheduleBackfillResponse, AutumnError> {
    let (actor, source, req_id) = audit_context(headers, api_state);
    let started_at = chrono::Utc::now();

    let schedule_id = parse_uuid(id, "schedule id")?;
    let pool = api_state.storage_pool().map_err(map_error)?;
    let runtime = api_state.runtime().map_err(map_error)?;

    if request.to < request.from {
        return Err(AutumnError::bad_request_msg(
            "backfill 'to' must be at or after 'from'",
        ));
    }

    // Load the schedule row (fan out across shards; schedule rows are not shard-assigned).
    let (schedule, schedule_shard) = load_schedule_by_id_with_shard(api_state, schedule_id).await?;

    // Respect paused state unless the caller explicitly opts in.
    if schedule.is_paused && !request.include_paused {
        return Err(AutumnError::bad_request_msg(format!(
            "schedule {schedule_id} is paused; pass include_paused=true to backfill a paused schedule"
        )));
    }

    // Reject exhausted schedules — bounds have been reached and no more runs
    // should start via any path (issue #478). Also check live bounds in case
    // the scheduler hasn't yet processed an already-violated row.
    {
        let now = chrono::Utc::now();
        let live_end_at_exceeded = schedule.end_at.is_some_and(|end| now >= end);
        let live_budget_exhausted = schedule
            .max_runs
            .is_some_and(|max| max > 0 && schedule.runs_started >= max);
        if schedule.exhausted_at.is_some() || live_end_at_exceeded || live_budget_exhausted {
            return Err(AutumnError::bad_request_msg(format!(
                "schedule {schedule_id} is exhausted (end_at or max_runs reached); \
                 extend the limits before backfilling"
            ))
            .with_status(axum::http::StatusCode::CONFLICT));
        }
    }

    let parsed_schedule = schedule
        .schedule_expr
        .as_deref()
        .and_then(parse_schedule_from_expr_pub);

    let max_count = request.max_count.unwrap_or(DEFAULT_BACKFILL_MAX_COUNT);

    let limit_err = |e| match e {
        BackfillPlanError::LimitExceeded { limit } => AutumnError::bad_request_msg(format!(
            "backfill window contains more than {limit} timestamps; lower the window or pass a higher max_count"
        )),
    };
    // Each entry is (original_slot, fire_time). original_slot is the raw cron timestamp
    // used for deterministic workflow-ID generation so that calendar rebasing (e.g.
    // RunNextBusinessDay / RunPrevBusinessDay) cannot cause two distinct logical slots
    // that adjust to the same day to collide on the derived workflow ID.
    let timestamp_pairs: Vec<BackfillSlot> = if let Some(ref cal_name) = schedule.calendar_name {
        let mut conn = acquire_conn(pool.default_pool()).await?;
        let excluded_dates = load_exclusions_for_calendar(&mut conn, cal_name)
            .await
            .map_err(map_error)?;
        let skip_policy = SkipPolicy::from_db(&schedule.skip_policy);
        let exclude_weekends = calendar_excludes_weekends(cal_name);
        plan_backfill_with_calendar(
            parsed_schedule.as_ref(),
            request.from,
            request.to,
            max_count,
            &excluded_dates,
            skip_policy,
            exclude_weekends,
        )
        .map_err(limit_err)?
    } else {
        plan_backfill_timestamps(
            parsed_schedule.as_ref(),
            request.from,
            request.to,
            max_count,
        )
        .map_err(limit_err)?
        .into_iter()
        .map(|ts| (ts, ts))
        .collect()
    };
    // Filter out any timestamp pairs whose effective fire time is at or past
    // end_at (issue #478). This is a belt-and-suspenders guard: the exhaustion
    // check above already rejects schedules whose end_at has passed at request
    // time, but a tight end_at window could still contain some past-cutoff slots
    // among an otherwise valid batch.
    let timestamp_pairs: Vec<_> = if let Some(end_at) = schedule.end_at {
        timestamp_pairs
            .into_iter()
            .filter(|(_, ft)| *ft < end_at)
            .collect()
    } else {
        timestamp_pairs
    };

    // fire_times is the calendar-adjusted list used for display and dedup checks.
    let fire_times: Vec<chrono::DateTime<chrono::Utc>> =
        timestamp_pairs.iter().map(|(_, ft)| *ft).collect();

    let total = timestamp_pairs.len();
    let (kind, name) = if let Some(ref dag_name) = schedule.dag_name {
        (ScheduleKind::Dag, dag_name.clone())
    } else if let Some(ref wf_name) = schedule.workflow_name {
        (ScheduleKind::Workflow, wf_name.clone())
    } else {
        return Err(AutumnError::service_unavailable_msg(
            "schedule row has neither dag_name nor workflow_name",
        ));
    };

    if kind == ScheduleKind::Dag && !runtime.is_registered_dag(&name) {
        return Err(AutumnError::not_found_msg(format!(
            "DAG '{name}' is not registered"
        )));
    }

    let max_active = i64::from(schedule.max_active_runs);

    if schedule.is_paused && request.include_paused && kind == ScheduleKind::Dag && !request.dry_run
    {
        return Err(AutumnError::bad_request_msg(format!(
            "paused DAG schedule {schedule_id} cannot be backfilled in non-dry-run mode; resume the schedule before dispatching backfill work"
        )));
    }

    // Dry-run: query current running count and project what would happen.
    if request.dry_run {
        let running = query_running_count_best_effort(&pool, &kind, &name, schedule_id).await;
        // Workflow IDs are derived from original_slot (not fire_time), so duplicate
        // detection must use the same set of timestamps that dispatch will use.
        let original_slots: Vec<_> = timestamp_pairs.iter().map(|(orig, _)| *orig).collect();
        let already_exists =
            count_existing_in_window(&pool, &kind, schedule_id, &name, &original_slots).await;
        let remaining = total.saturating_sub(already_exists);
        let available_slots = usize::try_from((max_active - running).max(0)).unwrap_or(0);
        // Mirror the dispatch loop's gates so the preview matches the real path: the
        // max_runs budget is checked first (#478), then max_active_runs concurrency.
        let budget_remaining: Option<usize> = schedule.max_runs.and_then(|max| {
            (max > 0)
                .then(|| {
                    usize::try_from((i64::from(max) - i64::from(schedule.runs_started)).max(0)).ok()
                })
                .flatten()
        });
        let budget_passed = budget_remaining.map_or(remaining, |b| remaining.min(b));
        let would_dispatch = budget_passed.min(available_slots);
        let would_skip_budget = remaining - budget_passed;
        let would_skip_max = budget_passed - would_dispatch;

        let mut skipped_reasons = std::collections::HashMap::new();
        if already_exists > 0 {
            skipped_reasons.insert("already_exists".to_string(), already_exists);
        }
        if would_skip_budget > 0 {
            skipped_reasons.insert("max_runs_exhausted".to_string(), would_skip_budget);
        }
        if would_skip_max > 0 {
            skipped_reasons.insert("max_active_runs".to_string(), would_skip_max);
        }

        let paused_schedule_warning = (schedule.is_paused
            && request.include_paused
            && kind == ScheduleKind::Dag)
            .then(|| {
                "Schedule is paused; backfilled DAG runs are QUEUED but will not \
                 execute until the schedule is resumed (`harvest schedule resume`)."
                    .to_string()
            });

        let would_skip = already_exists + would_skip_budget + would_skip_max;
        write_backfill_log(
            &pool,
            schedule_id,
            &actor,
            &source,
            request.from,
            request.to,
            true,
            total,
            would_dispatch,
            would_skip,
            0,
            "dry_run",
            None,
            started_at,
        )
        .await;
        write_audit(
            &pool,
            &actor,
            &source,
            req_id.as_deref(),
            route,
            id,
            STATUS_SUCCEEDED,
            None,
        )
        .await;
        return Ok(ScheduleBackfillResponse {
            status: "dry_run".to_string(),
            schedule_id,
            kind,
            name,
            from: request.from,
            to: request.to,
            planned_timestamps: fire_times.clone(),
            total,
            dispatched: would_dispatch,
            skipped: would_skip,
            failed: 0,
            skipped_reasons,
            partial_shard_failures: vec![],
            paused_schedule_warning,
        });
    }

    // Non-dry-run: dispatch each timestamp idempotently, respecting max_active_runs.
    let dag_default_queue = if kind == ScheduleKind::Dag {
        runtime
            .dags()
            .get(&name)
            .and_then(|dag| dag.default_queue.as_deref())
    } else {
        None
    };
    let dispatch_queue = schedule
        .queue_name
        .as_deref()
        .or(dag_default_queue)
        .unwrap_or("default");
    let mut dispatched = 0usize;
    let mut skipped = 0usize;
    let mut failed = 0usize;
    let mut shard_failures: Vec<BackfillShardFailure> = Vec::new();
    let mut skipped_reasons: std::collections::HashMap<String, usize> =
        std::collections::HashMap::new();

    // Warn when the operator uses include_paused=true for a paused DAG schedule.
    // `activate_queued_runs` skips paused schedules, so the inserted QUEUED runs
    // will not execute until the schedule is resumed.
    let paused_schedule_warning =
        (schedule.is_paused && request.include_paused && kind == ScheduleKind::Dag).then(|| {
            "Schedule is paused; backfilled DAG runs are QUEUED but will not \
             execute until the schedule is resumed (`harvest schedule resume`)."
                .to_string()
        });

    // Count running executions once before the loop; track dispatched_this_call separately
    // so we don't re-query on every timestamp. This value gates max_active_runs,
    // so non-dry-run dispatch must not treat count failures as zero.
    let running_at_start = match query_running_count(&pool, &kind, &name, schedule_id).await {
        Ok(count) => count,
        Err(count_failures) => {
            let status = "partial";
            let error_summary = Some("one or more shard failures");
            write_backfill_log(
                &pool,
                schedule_id,
                &actor,
                &source,
                request.from,
                request.to,
                false,
                total,
                0,
                0,
                total,
                status,
                error_summary,
                started_at,
            )
            .await;
            let id_str = schedule_id.to_string();
            write_audit(
                &pool,
                &actor,
                &source,
                req_id.as_deref(),
                route,
                &id_str,
                STATUS_FAILED,
                error_summary,
            )
            .await;

            return Ok(ScheduleBackfillResponse {
                status: status.to_string(),
                schedule_id,
                kind,
                name,
                from: request.from,
                to: request.to,
                planned_timestamps: fire_times.clone(),
                total,
                dispatched: 0,
                skipped: 0,
                failed: total,
                skipped_reasons,
                partial_shard_failures: count_failures,
                paused_schedule_warning,
            });
        }
    };
    // A throttled scheduled/backfill fire (issue #607) durably defers before any
    // `harvest_workflow_executions` row exists, so `running_at_start` above alone
    // undercounts a workflow schedule's true in-flight commitment: a separate,
    // later backfill request recomputing it from scratch would not see an
    // earlier request's still-pending deferred slots (they never became a
    // RUNNING/PAUSED execution) and could dispatch past `max_active_runs` --
    // the throttle scanner later fires those pending rows without re-checking
    // the schedule's overlap gate, so the violation would otherwise go uncaught
    // (code review, issue #607). DAG schedules have no throttle field at all
    // (`DagInfo` carries none), so this only applies to workflow schedules,
    // matching the earlier fix's precedent of scoping throttle-aware overlap
    // counting (`tick_one_workflow_schedule`/`drain_buffered_schedule_runs` in
    // scheduler.rs) to workflows only.
    let running_at_start = if kind == ScheduleKind::Workflow {
        match query_pending_throttle_count(&pool, &name).await {
            Ok(pending) => running_at_start + pending,
            Err(count_failures) => {
                let status = "partial";
                let error_summary = Some("one or more shard failures");
                write_backfill_log(
                    &pool,
                    schedule_id,
                    &actor,
                    &source,
                    request.from,
                    request.to,
                    false,
                    total,
                    0,
                    0,
                    total,
                    status,
                    error_summary,
                    started_at,
                )
                .await;
                let id_str = schedule_id.to_string();
                write_audit(
                    &pool,
                    &actor,
                    &source,
                    req_id.as_deref(),
                    route,
                    &id_str,
                    STATUS_FAILED,
                    error_summary,
                )
                .await;

                return Ok(ScheduleBackfillResponse {
                    status: status.to_string(),
                    schedule_id,
                    kind,
                    name,
                    from: request.from,
                    to: request.to,
                    planned_timestamps: fire_times.clone(),
                    total,
                    dispatched: 0,
                    skipped: 0,
                    failed: total,
                    skipped_reasons,
                    partial_shard_failures: count_failures,
                    paused_schedule_warning,
                });
            }
        }
    } else {
        running_at_start
    };
    let mut dispatched_this_call: i64 = 0;
    let mut budget_hit = false;
    // Atomic per-slot max_runs reservation runs on the schedule's OWN shard
    // (issue #688); schedule rows may live on a different shard than the
    // execution shard, exactly like trigger_schedule_now's budget accounting.
    //
    // Pool-connection safety (issue #688 review, Codex F4): the schedule-shard
    // connection used for budget accounting is chosen per loop arm below. In a
    // SINGLE-shard deployment the schedule shard and the execution shard are the
    // SAME pool, so we must NOT hold a second dedicated schedule connection across
    // the loop while each slot also checks out a per-slot exec `conn` — with a web
    // pool of size 1 (pool.rs only forbids size 0) that self-deadlocks (the route
    // waits on a connection it already holds). The original pre-#688 backfill held
    // exactly one connection at a time and was pool-size-1 safe; to keep that, when
    // `schedule_shard == exec_shard` (`same_pool`) budget ops reuse the per-slot
    // exec `conn` — all budget statements are sequential, never two concurrent
    // connections. Only for a GENUINELY different pool (multi-shard) do we hold a
    // separate schedule connection across the loop, where concurrent holds across
    // distinct pools don't contend. Assumption: distinct ShardIds map to distinct
    // pools in standard single/multi-shard topologies (single-shard always has
    // schedule_shard == exec_shard).

    match kind {
        ScheduleKind::Workflow => {
            let wf_name = name.clone();
            // Workflow schedules are always dispatched through the scheduler's own
            // connection, which uses `ExecutionId::new()` (ShardId::UNENCODED → default
            // shard). The backfill must write to the same shard so that the partial
            // unique index on (workflow_name, workflow_id) prevents the scheduler from
            // creating a second run for the same timestamp after the backfill window.
            let wf_shard_pool = pool.default_pool();
            // Budget-connection selection (Codex F4): the per-slot exec `conn` is drawn
            // from `pool.default_pool()`, which is backed by the pool's own default
            // shard — source `exec_shard` from there (not the router's default shard, a
            // separate field not asserted equal) so `same_pool` compares against the
            // shard that actually backs `conn`, keeping this arm self-consistent with
            // the DAG arm. When it equals the schedule shard, budget ops run on that
            // per-slot exec `conn` (pool-size-1 safe); otherwise hold a separate
            // schedule-pool connection across the loop (a distinct pool, safe to hold
            // concurrently with the exec pool).
            let exec_shard = pool.sharded_pool().default_shard();
            let same_pool = schedule_shard == exec_shard;
            let mut sched_conn_opt = if same_pool {
                None
            } else {
                Some(acquire_conn(pool.pool_for(schedule_shard)).await?)
            };
            for (original_slot, _fire_time) in &timestamp_pairs {
                // Once the atomic DB max_runs reservation (issue #688) fails for one
                // slot the budget is exhausted for every remaining slot too; report
                // each as skipped without another DB round-trip. The authoritative
                // budget check is the atomic conditional UPDATE below (after the
                // admission gate), which is race-safe against a concurrent backfill
                // or `trigger_schedule_now` (both use the same guarded UPDATE), but
                // NOT against the scheduler tick — the tick still gates `max_runs`
                // with an in-memory `live_runs_started` snapshot
                // (`scheduler.rs` `tick_one_workflow_schedule`), so a tick firing a
                // due slot concurrently on a near-capacity schedule can still jointly
                // over-run the budget. That is a pre-existing gap (identical for
                // `trigger_schedule_now`-vs-tick), out of scope for #688 (which fixes
                // the backfill-vs-backfill race); a complete fix would convert the
                // tick's in-loop budget gate to the same atomic reserve. The atomic
                // UPDATE replaces the prior stale in-memory
                // `runs_started + dispatched_this_call` snapshot check that could let
                // two concurrent requests both pass the gate with one remaining slot
                // (Codex P2, PR #677).
                if budget_hit {
                    skipped += 1;
                    *skipped_reasons
                        .entry("max_runs_exhausted".to_string())
                        .or_insert(0) += 1;
                    continue;
                }
                // In-memory budget attribution gate (issue #688): the atomic reservation below
                // is the authoritative race-safe gate, but it runs after the prior-run/max_active/
                // admission checks. Keep this cheap snapshot gate at loop position 1 so a slot
                // blocked purely because the (single-request) budget is spent is attributed
                // `max_runs_exhausted` and short-circuited BEFORE those later gates — preserving
                // the pre-#688 single-request skipped_reasons/status envelope. Stale under
                // concurrency (a concurrent request's reservations are invisible here), which is
                // exactly why the atomic reservation + `budget_hit` fast-path remain.
                if schedule.max_runs.is_some_and(|max| {
                    max > 0
                        && i64::from(schedule.runs_started) + dispatched_this_call >= i64::from(max)
                }) {
                    skipped += 1;
                    *skipped_reasons
                        .entry("max_runs_exhausted".to_string())
                        .or_insert(0) += 1;
                    continue;
                }
                // Respect max_active_runs: skip if we've already saturated the limit.
                if running_at_start + dispatched_this_call >= max_active {
                    skipped += 1;
                    *skipped_reasons
                        .entry("max_active_runs".to_string())
                        .or_insert(0) += 1;
                    continue;
                }

                // Use original_slot (pre-calendar-rebase) for ID so that two distinct
                // logical slots that calendar-adjust to the same fire_time do not collide.
                let workflow_id = scheduled_workflow_id_pub(schedule_id, &wf_name, *original_slot);
                let legacy_workflow_id = {
                    let micros = original_slot.timestamp_subsec_micros();
                    if micros == 0 {
                        format!("sched:{}:{}", wf_name, original_slot.timestamp())
                    } else {
                        format!(
                            "sched:{}:{}.{:06}",
                            wf_name,
                            original_slot.timestamp(),
                            micros
                        )
                    }
                };
                // Match the scheduler: ExecutionId::new() encodes ShardId::UNENCODED so
                // the execution lands on the default shard, same as tick_one_workflow_schedule.
                let exec_id = ExecutionId::new();
                let input = schedule
                    .workflow_input
                    .clone()
                    .unwrap_or(serde_json::Value::Null);

                let Ok(mut conn) = acquire_conn(wf_shard_pool).await else {
                    shard_failures.push(BackfillShardFailure {
                        shard_id: 0,
                        reason: "failed to acquire connection".to_string(),
                    });
                    failed += 1;
                    continue;
                };

                // Pre-check across ALL states including CONTINUED_AS_NEW / TERMINATED.
                // `start_or_load_workflow_execution` uses a partial unique index that
                // excludes sealed rows, so a sealed prior execution does not conflict
                // and would allow a duplicate to be created. Backfill must not reuse
                // sealed workflow IDs because the timestamp was already dispatched.
                let prior_check = harvest_workflow_executions::table
                    .filter(harvest_workflow_executions::workflow_name.eq(&wf_name))
                    .filter(
                        harvest_workflow_executions::workflow_id
                            .eq(&workflow_id)
                            .or(harvest_workflow_executions::workflow_id.eq(&legacy_workflow_id)),
                    )
                    .count()
                    .get_result::<i64>(&mut conn)
                    .await;
                match classify_backfill_prior_count(prior_check) {
                    BackfillPriorPrecheck::PriorRunExists => {
                        skipped += 1;
                        *skipped_reasons
                            .entry("already_exists".to_string())
                            .or_insert(0) += 1;
                        continue;
                    }
                    BackfillPriorPrecheck::NoPriorRun => {}
                    BackfillPriorPrecheck::PrecheckFailed(reason) => {
                        shard_failures.push(BackfillShardFailure {
                            shard_id: 0,
                            reason: format!(
                                "failed to check prior workflow execution for {workflow_id}: {reason}"
                            ),
                        });
                        failed += 1;
                        continue;
                    }
                }

                let (
                    owner,
                    runbook_url,
                    severity,
                    info_sla,
                    info_execution_timeout,
                    info_chain_execution_timeout,
                ) = runtime.registry.workflows.get(&wf_name).map_or(
                    (None, None, None, None, None, None),
                    |info| {
                        (
                            info.owner,
                            info.runbook_url,
                            info.severity,
                            info.sla,
                            info.execution_timeout,
                            info.chain_execution_timeout,
                        )
                    },
                );
                let sla = clamp_info_default_sla(info_sla, info_execution_timeout);
                // Issue #743 review (PR #1141, Finding #5): a workflow backfill
                // must ALSO thread the declared `execution_timeout` and the
                // fleet-wide `max_workflow_execution_timeout` ceiling into the
                // start below -- `info_execution_timeout` was already resolved
                // above (it feeds the `sla` clamp) but was never applied to the
                // execution row itself, leaving a backfilled run with no hard
                // deadline even when the workflow type declares one. Mirrors the
                // DAG branch's identical fix immediately below.
                let workflow_execution_timeout =
                    info_execution_timeout.and_then(|d| chrono::Duration::from_std(d).ok());
                let workflow_max_execution_timeout_ceiling = runtime
                    .registry
                    .max_workflow_execution_timeout
                    .and_then(|d| chrono::Duration::from_std(d).ok());

                // issue #377: check admission gates before firing a backfill run.
                // Workflow backfill writes to pool.default_pool() and creates
                // ExecutionId::new() (ShardId::UNENCODED) which resolves to the
                // configured default shard — use that shard ID here, not a
                // hard-coded 0 which is wrong when the default shard has a
                // different ID.
                if let Some((gate_id, gate_reason, scope_kind)) = api_state.gate_cache().check(
                    &wf_name,
                    dispatch_queue,
                    runtime.router.default_shard().as_i32(),
                    owner,
                ) {
                    let reason_label = match gate_reason.char_indices().nth(64) {
                        Some((idx2, _)) => &gate_reason[..idx2],
                        None => &gate_reason,
                    };
                    runtime
                        .registry
                        .telemetry()
                        .metrics
                        .record_admission_blocked(scope_kind, reason_label);
                    shard_failures.push(BackfillShardFailure {
                        shard_id: 0,
                        reason: format!("admission blocked by gate {gate_id}: {gate_reason}"),
                    });
                    failed += 1;
                    continue;
                }

                // Atomically reserve one max_runs slot on the schedule's own shard
                // BEFORE committing to a start (issue #688). Placed after the prior-run
                // and admission checks so a slot is reserved only for a run that will
                // actually attempt to start; every non-committing path below releases
                // it via `release_backfill_budget_slot`.
                let now = chrono::Utc::now();
                // Re-arm target for a release that clears a tick-nulled exhaustion
                // (F3/F5): restore the pre-tick due `next_run_at` snapshot loaded at
                // backfill request start, NOT a recompute from `now`. Recomputing from
                // `now` would advance PAST an already-due slot the tick skipped, dropping
                // that run for a catchup schedule; the snapshot is the exact slot to retry.
                // The re-arm UPDATE stays guarded on `next_run_at IS NULL`, so the common
                // intra-backfill case is a no-op and this only fires after the clear
                // un-exhausted a `max_runs_exhausted` row.
                let rearm_next = schedule.next_run_at;
                // The reserved `runs_started` value is intentionally unused: the
                // exhaustion transition below re-evaluates the LIVE row (issue #688,
                // Codex F6), so no request-start snapshot is threaded through.
                {
                    // same_pool → reuse the per-slot exec `conn`; else the separate
                    // schedule connection. `conn` is not otherwise borrowed here.
                    let budget_conn = sched_conn_opt.as_mut().unwrap_or(&mut conn);
                    match reserve_backfill_budget_slot(budget_conn, schedule_id, now).await {
                        Ok(Some(_)) => {}
                        Ok(None) => {
                            budget_hit = true;
                            skipped += 1;
                            *skipped_reasons
                                .entry("max_runs_exhausted".to_string())
                                .or_insert(0) += 1;
                            continue;
                        }
                        Err(e) => {
                            shard_failures.push(BackfillShardFailure {
                                shard_id: 0,
                                reason: format!("failed to reserve run budget: {e}"),
                            });
                            failed += 1;
                            continue;
                        }
                    }
                }

                // Start-throttle admission (issue #607): pace backfill admissions,
                // defer the excess rather than admitting an entire backfill window
                // at once. A deferred slot counts as dispatched (the timestamp is
                // consumed; schedule_id/scheduled_for/origin=backfill are persisted
                // so carryover (#488) and run-history (#534) lineage survive the
                // deferral) and is admitted later by the throttle scanner. Mirrors
                // `tick_one_workflow_schedule`'s throttle block (scheduler.rs) and
                // the size-check-ordering fix applied there and at the other three
                // call sites (issue #607 round 4).
                let mut backfill_throttle_bucket: Option<String> = None;
                if let Some((throttle_policy, resolved_throttle_key)) =
                    workflow_resolving_throttle(&runtime.registry, &wf_name, &input)
                {
                    let effective_cap = runtime
                        .registry
                        .workflows
                        .get(&wf_name)
                        .and_then(|info| info.max_input_bytes)
                        .map_or(runtime.registry.max_workflow_input_bytes, |per| {
                            per.max(runtime.registry.max_workflow_input_bytes)
                        });
                    let skip_cap_check = match autumn_harvest::throttle::skip_size_check(
                        &mut conn,
                        &wf_name,
                        &workflow_id,
                        Some("reject_duplicate"),
                    )
                    .await
                    {
                        Ok(skip) => skip,
                        Err(e) => {
                            let budget_conn = sched_conn_opt.as_mut().unwrap_or(&mut conn);
                            release_backfill_budget_slot(budget_conn, schedule_id, now, rearm_next)
                                .await;
                            shard_failures.push(BackfillShardFailure {
                                shard_id: 0,
                                reason: e.to_string(),
                            });
                            failed += 1;
                            continue;
                        }
                    };
                    if !skip_cap_check && effective_cap > 0 {
                        let observed =
                            serde_json::to_string(&input).map_or(0u64, |s| s.len() as u64);
                        if observed > effective_cap {
                            let budget_conn = sched_conn_opt.as_mut().unwrap_or(&mut conn);
                            release_backfill_budget_slot(budget_conn, schedule_id, now, rearm_next)
                                .await;
                            skipped += 1;
                            *skipped_reasons
                                .entry("oversized_input".to_string())
                                .or_insert(0) += 1;
                            continue;
                        }
                    }
                    let effective_retry = schedule
                        .retry_policy
                        .as_ref()
                        .and_then(|v| {
                            serde_json::from_value::<autumn_harvest::policy::RetryPolicy>(v.clone())
                                .ok()
                        })
                        .or_else(|| {
                            runtime
                                .registry
                                .workflows
                                .get(&wf_name)
                                .and_then(|info| info.retry_policy.clone())
                        })
                        .and_then(|p| serde_json::to_value(&p).ok());
                    let start_options = autumn_harvest::debounce::DebounceStartOptions {
                        reuse_policy: Some("reject_duplicate".to_string()),
                        // Issue #743 review (PR #1141, Finding #5): a throttled
                        // (deferred) backfill fire must ALSO carry the declared
                        // execution_timeout + fleet-wide ceiling -- parity with
                        // the non-throttled backfill start path fixed above, and
                        // with the `chain_execution_timeout_secs` field below,
                        // which was already threaded correctly.
                        execution_timeout_secs: workflow_execution_timeout.map(|d| d.num_seconds()),
                        memo: None,
                        search_attrs: None,
                        sla_secs: sla.map(|d| d.num_seconds()),
                        context_headers: None,
                        priority: None,
                        concurrency_key: None,
                        concurrency_limit: None,
                        concurrency_on_conflict: None,
                        owner: owner.map(str::to_string),
                        runbook_url: runbook_url.map(str::to_string),
                        severity: severity.map(str::to_string),
                        max_execution_timeout_ceiling_secs: workflow_max_execution_timeout_ceiling
                            .map(|d| d.num_seconds()),
                        // Chain-scoped lifetime cap (issue #617): workflow-type
                        // default + fleet-wide ceiling captured so a throttled
                        // backfill fire keeps the cap (parity with the non-throttled
                        // backfill start path).
                        chain_execution_timeout_secs: info_chain_execution_timeout
                            .and_then(|d| chrono::Duration::from_std(d).ok())
                            .map(|d| d.num_seconds()),
                        max_workflow_chain_timeout_ceiling_secs: api_state
                            .max_workflow_chain_timeout()
                            .and_then(|d| chrono::Duration::from_std(d).ok())
                            .map(|d| d.num_seconds()),
                        max_workflow_input_bytes: Some(effective_cap),
                        trace_context: None,
                        workflow_retry_policy: effective_retry,
                        max_workflow_attempts_ceiling: runtime
                            .registry
                            .max_workflow_attempts_ceiling,
                        completion_callbacks: None,
                        schedule_id: Some(schedule_id),
                        scheduled_for: Some(*original_slot),
                        origin: Some(autumn_harvest::execution::ORIGIN_BACKFILL.to_string()),
                        // Schedule backfill (issue #740): provenance is
                        // `backfill`, referencing the schedule id, operator.
                        start_source: Some(
                            autumn_harvest::StartSource::Backfill.as_str().to_string(),
                        ),
                        start_source_ref: Some(schedule_id.to_string()),
                        started_by: Some(actor.clone()),
                    };
                    match autumn_harvest::throttle::reserve_or_defer(
                        &mut conn,
                        autumn_harvest::throttle::AdmitThrottleParams {
                            workflow_name: &wf_name,
                            throttle_key: &resolved_throttle_key,
                            workflow_id: &workflow_id,
                            queue_name: dispatch_queue,
                            input: input.clone(),
                            start_options,
                            refill_per_sec: throttle_policy.refill_per_sec,
                            burst: throttle_policy.burst,
                            schedule_to_start: throttle_policy.schedule_to_start,
                            shard_id: runtime.router.default_shard().as_i32(),
                        },
                    )
                    .await
                    {
                        Ok(autumn_harvest::throttle::ThrottleAdmission::Deferred(outcome)) => {
                            if outcome.fresh {
                                runtime
                                    .registry
                                    .telemetry()
                                    .metrics
                                    .record_start_throttled(&wf_name);
                                dispatched += 1;
                                dispatched_this_call += 1;
                                let budget_conn = sched_conn_opt.as_mut().unwrap_or(&mut conn);
                                transition_backfill_exhausted_if_reached(
                                    budget_conn,
                                    schedule_id,
                                    now,
                                )
                                .await;
                            } else {
                                // A repeated backfill call for a window whose
                                // slot is still durably deferred from an
                                // earlier call resolves to the *same* pending
                                // row (`reserve_or_defer`'s idempotency
                                // shortcut), not a new admission. Report it as
                                // already-consumed rather than a fresh
                                // dispatch, so a repeated identical backfill
                                // request can't double-count the slot as
                                // dispatched or double-spend max_runs budget
                                // for it (code review, issue #607).
                                let budget_conn = sched_conn_opt.as_mut().unwrap_or(&mut conn);
                                release_backfill_budget_slot(
                                    budget_conn,
                                    schedule_id,
                                    now,
                                    rearm_next,
                                )
                                .await;
                                skipped += 1;
                                *skipped_reasons
                                    .entry("already_exists".to_string())
                                    .or_insert(0) += 1;
                            }
                            continue;
                        }
                        Ok(autumn_harvest::throttle::ThrottleAdmission::Reserved {
                            bucket_key,
                        }) => {
                            backfill_throttle_bucket = Some(bucket_key);
                            // Fall through to the normal start below, on the same
                            // connection.
                        }
                        Ok(autumn_harvest::throttle::ThrottleAdmission::Bypassed) => {
                            // Active execution already resolves this reuse policy
                            // as a no-op; no token reserved, fall through.
                        }
                        Err(e) => {
                            let budget_conn = sched_conn_opt.as_mut().unwrap_or(&mut conn);
                            release_backfill_budget_slot(budget_conn, schedule_id, now, rearm_next)
                                .await;
                            shard_failures.push(BackfillShardFailure {
                                shard_id: 0,
                                reason: e.to_string(),
                            });
                            failed += 1;
                            continue;
                        }
                    }
                }

                // Provenance for a non-throttled workflow backfill (issue #740):
                // `backfill`, referencing the schedule id and the operator actor —
                // matching the throttled branch above.
                let schedule_id_str = schedule_id.to_string();
                let result = start_or_load_workflow_execution_with_metrics_and_codecs(
                    &mut conn,
                    StartWorkflowParams {
                        workflow_name: &wf_name,
                        workflow_id: &workflow_id,
                        exec_id,
                        input: input.clone(),
                        parent_id: None,
                        queue_name: dispatch_queue,
                        execution_timeout: workflow_execution_timeout,
                        memo: None,
                        search_attrs: None,
                        reuse_policy: WorkflowIdReusePolicy::RejectDuplicate,
                        conflict_policy:
                            autumn_harvest::types::WorkflowIdConflictPolicy::Unspecified,
                        trace_context: None,
                        max_execution_timeout_ceiling: workflow_max_execution_timeout_ceiling,
                        // Chain-scoped lifetime cap (issue #617): backfilled runs
                        // inherit the workflow-type default + fleet-wide
                        // ceiling-as-default so a whole scheduled chain is capped
                        // even when a workflow under-specifies (AC4).
                        chain_execution_timeout: info_chain_execution_timeout
                            .and_then(|d| chrono::Duration::from_std(d).ok()),
                        max_workflow_chain_timeout_ceiling: api_state
                            .max_workflow_chain_timeout()
                            .map(|d| {
                                chrono::Duration::from_std(d).unwrap_or(chrono::Duration::MAX)
                            }),
                        inherited_chain_deadline_at: None,
                        concurrency_key: None,
                        concurrency_limit: None,
                        concurrency_on_conflict:
                            autumn_harvest::concurrency::ConcurrencyOnConflict::Defer,
                        priority: Priority::default(),
                        max_workflow_input_bytes: runtime
                            .registry
                            .workflows
                            .get(&wf_name)
                            .and_then(|info| info.max_input_bytes)
                            .map_or(runtime.registry.max_workflow_input_bytes, |per| {
                                per.max(runtime.registry.max_workflow_input_bytes)
                            }),
                        start_at: None,
                        delay: None,
                        max_workflow_start_delay: None,
                        owner,
                        runbook_url,
                        severity,
                        context_headers: None,
                        sla,
                        // Backfilled runs share the schedule's carryover lineage (issue #488).
                        schedule_id: Some(schedule_id),
                        scheduled_for: Some(*original_slot),
                        workflow_attempt: 1,
                        workflow_retry_policy: schedule
                            .retry_policy
                            .as_ref()
                            .and_then(|v| serde_json::from_value(v.clone()).ok())
                            .or_else(|| {
                                runtime
                                    .registry
                                    .workflows
                                    .get(&wf_name)
                                    .and_then(|info| info.retry_policy.clone())
                            }),
                        retry_of_exec_id: None,
                        max_workflow_attempts_ceiling: runtime
                            .registry
                            .max_workflow_attempts_ceiling,
                        // Distinguish a backfill storm from normal cadence (issue #534).
                        origin: Some(autumn_harvest::execution::ORIGIN_BACKFILL),
                        completion_callbacks: None,
                        start_source: autumn_harvest::StartSource::Backfill,
                        start_source_ref: Some(&schedule_id_str),
                        started_by: Some(actor.as_str()),
                    },
                    Some(runtime.registry.telemetry().metrics.as_ref()),
                    None,
                    runtime.registry.payload_codecs(),
                )
                .await;
                match result {
                    Ok(started) if started.created => {
                        dispatched += 1;
                        dispatched_this_call += 1;
                        let budget_conn = sched_conn_opt.as_mut().unwrap_or(&mut conn);
                        transition_backfill_exhausted_if_reached(budget_conn, schedule_id, now)
                            .await;
                    }
                    Ok(_) | Err(HarvestError::AlreadyExists { .. }) => {
                        // AC-a: an id-reuse short-circuit consumed no admission —
                        // refund the reserved throttle token FIRST (that `&mut conn`
                        // borrow must end before `budget_conn` may re-borrow `conn`
                        // in the same_pool case), then release the reserved max_runs
                        // slot (issue #688).
                        if let Some(ref bucket) = backfill_throttle_bucket {
                            let _ =
                                autumn_harvest::queue::refund_rate_limit_token(&mut conn, bucket)
                                    .await;
                        }
                        let budget_conn = sched_conn_opt.as_mut().unwrap_or(&mut conn);
                        release_backfill_budget_slot(budget_conn, schedule_id, now, rearm_next)
                            .await;
                        skipped += 1;
                        *skipped_reasons
                            .entry("already_exists".to_string())
                            .or_insert(0) += 1;
                    }
                    Err(e) => {
                        // No run admitted — refund the reserved throttle token FIRST
                        // (borrow-ordering, as above), then release the reserved
                        // max_runs slot (issue #688) before propagating the failure.
                        if let Some(ref bucket) = backfill_throttle_bucket {
                            let _ =
                                autumn_harvest::queue::refund_rate_limit_token(&mut conn, bucket)
                                    .await;
                        }
                        let budget_conn = sched_conn_opt.as_mut().unwrap_or(&mut conn);
                        release_backfill_budget_slot(budget_conn, schedule_id, now, rearm_next)
                            .await;
                        shard_failures.push(BackfillShardFailure {
                            shard_id: 0,
                            reason: e.to_string(),
                        });
                        failed += 1;
                    }
                }
            }
        }
        ScheduleKind::Dag => {
            let dag_name = name.clone();
            let shard_id = runtime.router().pick_for_dag(&dag_name);
            let shard_pool = pool.pool_for(shard_id);
            // Budget-connection selection (Codex F4): when the DAG exec shard equals
            // the schedule shard, budget ops run on the per-slot exec `conn`
            // (pool-size-1 safe); otherwise hold a separate schedule-pool connection.
            let same_pool = schedule_shard == shard_id;
            let mut sched_conn_opt = if same_pool {
                None
            } else {
                Some(acquire_conn(pool.pool_for(schedule_shard)).await?)
            };

            for (original_slot, _fire_time) in &timestamp_pairs {
                // Once the atomic DB max_runs reservation (issue #688) fails for one
                // slot the budget is exhausted for every remaining slot too — see the
                // workflow loop. The authoritative atomic reservation below is race-safe
                // against a concurrent backfill or `trigger_schedule_now`, but NOT the
                // scheduler tick (its in-memory `live_runs_started` gate can still jointly
                // over-run a near-capacity schedule — a pre-existing gap, out of scope for
                // #688). Replaces the prior stale in-memory snapshot check.
                if budget_hit {
                    skipped += 1;
                    *skipped_reasons
                        .entry("max_runs_exhausted".to_string())
                        .or_insert(0) += 1;
                    continue;
                }
                // In-memory budget attribution gate (issue #688): the atomic reservation below
                // is the authoritative race-safe gate, but it runs after the prior-run/max_active/
                // admission checks. Keep this cheap snapshot gate at loop position 1 so a slot
                // blocked purely because the (single-request) budget is spent is attributed
                // `max_runs_exhausted` and short-circuited BEFORE those later gates — preserving
                // the pre-#688 single-request skipped_reasons/status envelope. Stale under
                // concurrency (a concurrent request's reservations are invisible here), which is
                // exactly why the atomic reservation + `budget_hit` fast-path remain.
                if schedule.max_runs.is_some_and(|max| {
                    max > 0
                        && i64::from(schedule.runs_started) + dispatched_this_call >= i64::from(max)
                }) {
                    skipped += 1;
                    *skipped_reasons
                        .entry("max_runs_exhausted".to_string())
                        .or_insert(0) += 1;
                    continue;
                }
                // Respect max_active_runs for DAGs (now counted via workflow executions).
                if running_at_start + dispatched_this_call >= max_active {
                    skipped += 1;
                    *skipped_reasons
                        .entry("max_active_runs".to_string())
                        .or_insert(0) += 1;
                    continue;
                }

                let Ok(mut conn) = acquire_conn(shard_pool).await else {
                    shard_failures.push(BackfillShardFailure {
                        shard_id: shard_id.as_i32(),
                        reason: "failed to acquire connection".to_string(),
                    });
                    failed += 1;
                    continue;
                };
                // Use original_slot for ID, same as the workflow path above.
                let workflow_id = scheduled_workflow_id_pub(schedule_id, &dag_name, *original_slot);
                let legacy_workflow_id = {
                    let micros = original_slot.timestamp_subsec_micros();
                    if micros == 0 {
                        format!("sched:{}:{}", dag_name, original_slot.timestamp())
                    } else {
                        format!(
                            "sched:{}:{}.{:06}",
                            dag_name,
                            original_slot.timestamp(),
                            micros
                        )
                    }
                };
                let exec_id = autumn_harvest::types::ExecutionId::new_for_shard(shard_id);
                let dag_queue = schedule
                    .queue_name
                    .as_deref()
                    .or(dag_default_queue)
                    .unwrap_or("default");

                // Pre-check across ALL states including CONTINUED_AS_NEW / TERMINATED.
                // start_or_load_workflow_execution uses a partial unique index that
                // excludes sealed rows, so a sealed prior run wouldn't conflict and
                // a duplicate would be created for the same scheduled slot.
                let prior_check = harvest_workflow_executions::table
                    .filter(harvest_workflow_executions::workflow_name.eq(&dag_name))
                    .filter(
                        harvest_workflow_executions::workflow_id
                            .eq(&workflow_id)
                            .or(harvest_workflow_executions::workflow_id.eq(&legacy_workflow_id)),
                    )
                    .count()
                    .get_result::<i64>(&mut conn)
                    .await;
                match classify_backfill_prior_count(prior_check) {
                    BackfillPriorPrecheck::PriorRunExists => {
                        skipped += 1;
                        *skipped_reasons
                            .entry("already_exists".to_string())
                            .or_insert(0) += 1;
                        continue;
                    }
                    BackfillPriorPrecheck::NoPriorRun => {}
                    BackfillPriorPrecheck::PrecheckFailed(reason) => {
                        shard_failures.push(BackfillShardFailure {
                            shard_id: shard_id.as_i32(),
                            reason: format!(
                                "failed to check prior DAG execution for {workflow_id}: {reason}"
                            ),
                        });
                        failed += 1;
                        continue;
                    }
                }

                let (owner, runbook_url, severity) =
                    runtime
                        .dags()
                        .get(&dag_name)
                        .map_or((None, None, None), |dag| {
                            (
                                dag.owner.as_deref(),
                                dag.runbook_url.as_deref(),
                                dag.severity.as_deref(),
                            )
                        });

                // Issue #743 review (PR #1141, Finding #5): a DAG backfill must
                // thread the DAG's declared execution_timeout/sla, and the
                // fleet-wide max_workflow_execution_timeout ceiling, the SAME
                // way the scheduler tick's dispatch path and a manual/MCP
                // trigger (`trigger_unified_dag`) already do -- resolved from the
                // DAG's own shadow `WorkflowInfo`, registered under `dag_name` in
                // `registry.workflows` by `DagInfo::as_workflow_info()`. Kept as a
                // separate lookup from the `(owner, runbook_url, severity)` tuple
                // above (sourced from `runtime.dags()`) so this fix stays scoped
                // to the deadline fields and never touches classic-DAG behavior
                // for those three unrelated fields. `chain_execution_timeout` is
                // deliberately left `None` for a DAG start (issue #617: DAGs
                // carry no chain-scoped lifetime cap), matching
                // `DagInfo::as_workflow_info()`'s own `chain_execution_timeout:
                // None`.
                let dag_wf_info = runtime.registry.workflows.get(&dag_name);
                let dag_execution_timeout = dag_wf_info
                    .and_then(|info| info.execution_timeout)
                    .and_then(|d| chrono::Duration::from_std(d).ok());
                let dag_sla = dag_wf_info
                    .and_then(|info| info.sla)
                    .and_then(|d| chrono::Duration::from_std(d).ok());
                let dag_max_execution_timeout_ceiling = runtime
                    .registry
                    .max_workflow_execution_timeout
                    .and_then(|d| chrono::Duration::from_std(d).ok());

                // issue #377: enforce admission gates for DAG backfills, mirroring
                // the workflow backfill branch gate check.
                if let Some((gate_id, gate_reason, scope_kind)) =
                    api_state
                        .gate_cache()
                        .check(&dag_name, dag_queue, shard_id.as_i32(), owner)
                {
                    let reason_label = match gate_reason.char_indices().nth(64) {
                        Some((idx2, _)) => &gate_reason[..idx2],
                        None => &gate_reason,
                    };
                    runtime
                        .registry
                        .telemetry()
                        .metrics
                        .record_admission_blocked(scope_kind, reason_label);
                    shard_failures.push(BackfillShardFailure {
                        shard_id: shard_id.as_i32(),
                        reason: format!("admission blocked by gate {gate_id}: {gate_reason}"),
                    });
                    failed += 1;
                    continue;
                }

                // Atomically reserve one max_runs slot on the schedule's own shard
                // BEFORE committing to a start (issue #688). Placed after the prior-run
                // and admission checks; every non-committing path below releases it.
                let now = chrono::Utc::now();
                // Re-arm target for a release that clears a tick-nulled exhaustion
                // (F3/F5): restore the pre-tick due `next_run_at` snapshot loaded at
                // backfill request start, NOT a recompute from `now`. Recomputing from
                // `now` would advance PAST an already-due slot the tick skipped, dropping
                // that run for a catchup schedule; the snapshot is the exact slot to retry.
                // The re-arm UPDATE stays guarded on `next_run_at IS NULL`, so the common
                // intra-backfill case is a no-op and this only fires after the clear
                // un-exhausted a `max_runs_exhausted` row.
                let rearm_next = schedule.next_run_at;
                // The reserved `runs_started` value is intentionally unused: the
                // exhaustion transition below re-evaluates the LIVE row (issue #688,
                // Codex F6), so no request-start snapshot is threaded through.
                {
                    // same_pool → reuse the per-slot exec `conn`; else the separate
                    // schedule connection. `conn` is not otherwise borrowed here.
                    let budget_conn = sched_conn_opt.as_mut().unwrap_or(&mut conn);
                    match reserve_backfill_budget_slot(budget_conn, schedule_id, now).await {
                        Ok(Some(_)) => {}
                        Ok(None) => {
                            budget_hit = true;
                            skipped += 1;
                            *skipped_reasons
                                .entry("max_runs_exhausted".to_string())
                                .or_insert(0) += 1;
                            continue;
                        }
                        Err(e) => {
                            shard_failures.push(BackfillShardFailure {
                                shard_id: shard_id.as_i32(),
                                reason: format!("failed to reserve run budget: {e}"),
                            });
                            failed += 1;
                            continue;
                        }
                    }
                }

                // Provenance for a non-throttled DAG backfill (issue #740):
                // `backfill`, referencing the schedule id and the operator actor.
                let schedule_id_str = schedule_id.to_string();
                let start_result = start_or_load_workflow_execution_with_metrics_and_codecs(
                    &mut conn,
                    StartWorkflowParams {
                        workflow_name: &dag_name,
                        workflow_id: &workflow_id,
                        exec_id,
                        input: serde_json::json!({"_harvest_run_source": "backfill"}),
                        parent_id: None,
                        queue_name: dag_queue,
                        execution_timeout: dag_execution_timeout,
                        memo: None,
                        search_attrs: None,
                        reuse_policy: autumn_harvest::types::WorkflowIdReusePolicy::RejectDuplicate,
                        conflict_policy:
                            autumn_harvest::types::WorkflowIdConflictPolicy::Unspecified,
                        trace_context: None,
                        max_execution_timeout_ceiling: dag_max_execution_timeout_ceiling,
                        chain_execution_timeout: None,
                        max_workflow_chain_timeout_ceiling: None,
                        inherited_chain_deadline_at: None,
                        concurrency_key: None,
                        concurrency_limit: None,
                        concurrency_on_conflict:
                            autumn_harvest::concurrency::ConcurrencyOnConflict::Defer,
                        priority: Priority::default(),
                        max_workflow_input_bytes: 0,
                        start_at: None,
                        delay: None,
                        max_workflow_start_delay: None,
                        owner,
                        runbook_url,
                        severity,
                        context_headers: None,

                        sla: dag_sla,
                        // Backfilled runs share the schedule's carryover lineage (issue #488).
                        schedule_id: Some(schedule_id),
                        scheduled_for: Some(*original_slot),
                        workflow_attempt: 1,
                        workflow_retry_policy: schedule
                            .retry_policy
                            .as_ref()
                            .and_then(|v| serde_json::from_value(v.clone()).ok()),
                        retry_of_exec_id: None,
                        max_workflow_attempts_ceiling: runtime
                            .registry
                            .max_workflow_attempts_ceiling,
                        // Distinguish a backfill storm from normal cadence (issue #534).
                        origin: Some(autumn_harvest::execution::ORIGIN_BACKFILL),
                        completion_callbacks: None,
                        start_source: autumn_harvest::StartSource::Backfill,
                        start_source_ref: Some(&schedule_id_str),
                        started_by: Some(actor.as_str()),
                    },
                    Some(runtime.registry.telemetry().metrics.as_ref()),
                    None,
                    runtime.registry.payload_codecs(),
                )
                .await;
                match start_result {
                    Ok(started) if started.created => {
                        dispatched += 1;
                        dispatched_this_call += 1;
                        let budget_conn = sched_conn_opt.as_mut().unwrap_or(&mut conn);
                        transition_backfill_exhausted_if_reached(budget_conn, schedule_id, now)
                            .await;
                    }
                    Ok(_) => {
                        // RejectDuplicate → already exists; release the reserved slot (#688).
                        let budget_conn = sched_conn_opt.as_mut().unwrap_or(&mut conn);
                        release_backfill_budget_slot(budget_conn, schedule_id, now, rearm_next)
                            .await;
                        skipped += 1;
                        *skipped_reasons
                            .entry("already_exists".to_string())
                            .or_insert(0) += 1;
                    }
                    Err(autumn_harvest::HarvestError::AlreadyExists { .. }) => {
                        let budget_conn = sched_conn_opt.as_mut().unwrap_or(&mut conn);
                        release_backfill_budget_slot(budget_conn, schedule_id, now, rearm_next)
                            .await;
                        skipped += 1;
                        *skipped_reasons
                            .entry("already_exists".to_string())
                            .or_insert(0) += 1;
                    }
                    Err(e) => {
                        let budget_conn = sched_conn_opt.as_mut().unwrap_or(&mut conn);
                        release_backfill_budget_slot(budget_conn, schedule_id, now, rearm_next)
                            .await;
                        shard_failures.push(BackfillShardFailure {
                            shard_id: shard_id.as_i32(),
                            reason: e.to_string(),
                        });
                        failed += 1;
                    }
                }
            }
        }
    }

    // Budget is now consumed per-slot atomically via `reserve_backfill_budget_slot`
    // (issue #688) inside the dispatch loops, replacing the prior post-loop batch
    // increment which raced against concurrent requests. `dispatched_this_call`
    // still gates `max_active_runs` above, but no longer drives budget accounting.

    let status = if shard_failures.is_empty() && failed == 0 {
        "complete"
    } else {
        "partial"
    };
    let error_summary = if status == "partial" {
        Some("one or more shard failures")
    } else {
        None
    };

    write_backfill_log(
        &pool,
        schedule_id,
        &actor,
        &source,
        request.from,
        request.to,
        false,
        total,
        dispatched,
        skipped,
        failed,
        status,
        error_summary,
        started_at,
    )
    .await;
    let id_str = schedule_id.to_string();
    write_audit(
        &pool,
        &actor,
        &source,
        req_id.as_deref(),
        route,
        &id_str,
        if status == "complete" {
            STATUS_SUCCEEDED
        } else {
            STATUS_FAILED
        },
        error_summary,
    )
    .await;

    Ok(ScheduleBackfillResponse {
        status: status.to_string(),
        schedule_id,
        kind,
        name,
        from: request.from,
        to: request.to,
        planned_timestamps: fire_times,
        total,
        dispatched,
        skipped,
        failed,
        skipped_reasons,
        partial_shard_failures: shard_failures,
        paused_schedule_warning,
    })
}

/// Count active (RUNNING or PAUSED) workflow executions or DAG runs for the
/// named entity. A PAUSED run still occupies an active slot for
/// `max_active_runs`/overlap enforcement (issue #383), matching the scheduler.
/// The `schedule_id` disjunct (issue #1160) also counts a cross-type
/// continue-as-new successor of this schedule, matching
/// `scheduler::schedule_running_basis`.
/// Returns the total count across all shards, or all shard failures that made
/// the count unsafe to use for `max_active_runs` enforcement.
async fn query_running_count(
    pool: &HarvestDbPool,
    kind: &ScheduleKind,
    name: &str,
    schedule_id: uuid::Uuid,
) -> Result<i64, Vec<BackfillShardFailure>> {
    let mut total = 0i64;
    let mut failures = Vec::new();
    for (shard_id, shard_pool) in pool.iter_shards() {
        let Ok(mut conn) = acquire_conn(shard_pool).await else {
            failures.push(BackfillShardFailure {
                shard_id: shard_id.as_i32(),
                reason: "failed to acquire connection while counting running backfill slots"
                    .to_string(),
            });
            continue;
        };
        // Both DAG and Workflow kinds query harvest_workflow_executions since
        // DAGs are now unified as workflows (issue #256 step 5).
        let count_result = harvest_workflow_executions::table
            .filter(
                harvest_workflow_executions::workflow_name
                    .eq(name)
                    .or(harvest_workflow_executions::schedule_id.eq(Some(schedule_id))),
            )
            .filter(harvest_workflow_executions::state.eq_any(["RUNNING", "PAUSED"]))
            .count()
            .get_result::<i64>(&mut conn)
            .await;
        let _ = kind; // consumed for pattern coverage above
        match classify_backfill_running_count(count_result) {
            BackfillRunningCountCheck::Count(count) => total += count,
            BackfillRunningCountCheck::CountFailed(reason) => {
                failures.push(BackfillShardFailure {
                    shard_id: shard_id.as_i32(),
                    reason: format!("failed to count running backfill slots: {reason}"),
                });
            }
        }
    }
    if failures.is_empty() {
        Ok(total)
    } else {
        Err(failures)
    }
}

/// Dry-run uses the running-count estimate for operator preview only, so it
/// stays best-effort and preserves the historical conservative response shape.
async fn query_running_count_best_effort(
    pool: &HarvestDbPool,
    kind: &ScheduleKind,
    name: &str,
    schedule_id: uuid::Uuid,
) -> i64 {
    query_running_count(pool, kind, name, schedule_id)
        .await
        .unwrap_or(0)
}

/// Fan out across shards summing pending (not-yet-fired) start-throttle rows
/// (issue #607) for workflow `name`, mirroring `query_running_count`'s shape
/// and shard scope. Used to fold a workflow schedule's already-deferred
/// backfill slots into `running_at_start` so a subsequent, separate backfill
/// request can't dispatch (and defer) past `max_active_runs` while an earlier
/// request's deferred slots are still sitting in the throttle queue, never
/// having become a real execution `query_running_count` alone would see.
async fn query_pending_throttle_count(
    pool: &HarvestDbPool,
    name: &str,
) -> Result<i64, Vec<BackfillShardFailure>> {
    let mut total = 0i64;
    let mut failures = Vec::new();
    for (shard_id, shard_pool) in pool.iter_shards() {
        let Ok(mut conn) = acquire_conn(shard_pool).await else {
            failures.push(BackfillShardFailure {
                shard_id: shard_id.as_i32(),
                reason: "failed to acquire connection while counting pending throttled \
                         backfill slots"
                    .to_string(),
            });
            continue;
        };
        match autumn_harvest::throttle::pending_throttle_count_for_workflow(&mut conn, name).await {
            Ok(count) => total += count,
            Err(e) => failures.push(BackfillShardFailure {
                shard_id: shard_id.as_i32(),
                reason: format!("failed to count pending throttled backfill slots: {e}"),
            }),
        }
    }
    if failures.is_empty() {
        Ok(total)
    } else {
        Err(failures)
    }
}

/// Count how many of the planned timestamps already have an execution or DAG run.
/// Used in dry-run mode to improve the accuracy of the would-dispatch estimate.
/// Returns 0 on any DB error (safe: slightly over-estimates would-dispatch).
async fn count_existing_in_window(
    pool: &HarvestDbPool,
    kind: &ScheduleKind,
    schedule_id: uuid::Uuid,
    name: &str,
    timestamps: &[chrono::DateTime<chrono::Utc>],
) -> usize {
    if timestamps.is_empty() {
        return 0;
    }
    let mut total = 0usize;
    match kind {
        ScheduleKind::Workflow => {
            let mut workflow_ids: Vec<String> = timestamps
                .iter()
                .map(|ts| scheduled_workflow_id_pub(schedule_id, name, *ts))
                .collect();
            let legacy_ids: Vec<String> = timestamps
                .iter()
                .map(|ts| {
                    let micros = ts.timestamp_subsec_micros();
                    if micros == 0 {
                        format!("sched:{}:{}", name, ts.timestamp())
                    } else {
                        format!("sched:{}:{}.{:06}", name, ts.timestamp(), micros)
                    }
                })
                .collect();
            workflow_ids.extend(legacy_ids);
            for (_, shard_pool) in pool.iter_shards() {
                let Ok(mut conn) = acquire_conn(shard_pool).await else {
                    continue;
                };
                let count: i64 = harvest_workflow_executions::table
                    .filter(harvest_workflow_executions::workflow_name.eq(name))
                    .filter(harvest_workflow_executions::workflow_id.eq_any(&workflow_ids))
                    .count()
                    .get_result(&mut conn)
                    .await
                    .unwrap_or(0);
                total += usize::try_from(count).unwrap_or(0);
            }
        }
        ScheduleKind::Dag => {
            let mut workflow_ids: Vec<String> = timestamps
                .iter()
                .map(|ts| scheduled_workflow_id_pub(schedule_id, name, *ts))
                .collect();
            let legacy_ids: Vec<String> = timestamps
                .iter()
                .map(|ts| {
                    let micros = ts.timestamp_subsec_micros();
                    if micros == 0 {
                        format!("sched:{}:{}", name, ts.timestamp())
                    } else {
                        format!("sched:{}:{}.{:06}", name, ts.timestamp(), micros)
                    }
                })
                .collect();
            workflow_ids.extend(legacy_ids);
            for (_, shard_pool) in pool.iter_shards() {
                let Ok(mut conn) = acquire_conn(shard_pool).await else {
                    continue;
                };
                let count: i64 = harvest_workflow_executions::table
                    .filter(harvest_workflow_executions::workflow_name.eq(name))
                    .filter(harvest_workflow_executions::workflow_id.eq_any(&workflow_ids))
                    .count()
                    .get_result(&mut conn)
                    .await
                    .unwrap_or(0);
                total += usize::try_from(count).unwrap_or(0);
            }
        }
    }
    total
}

/// Write a backfill log row; silently swallows errors (best-effort durability).
#[allow(clippy::too_many_arguments)]
async fn write_backfill_log(
    pool: &HarvestDbPool,
    schedule_id: uuid::Uuid,
    actor: &str,
    source: &str,
    from: chrono::DateTime<chrono::Utc>,
    to: chrono::DateTime<chrono::Utc>,
    dry_run: bool,
    total: usize,
    dispatched: usize,
    skipped: usize,
    failed: usize,
    status: &str,
    error_summary: Option<&str>,
    started_at: chrono::DateTime<chrono::Utc>,
) {
    let Ok(mut conn) = acquire_conn(pool.default_pool()).await else {
        return;
    };
    let row = NewBackfillLogRow {
        id: uuid::Uuid::new_v4(),
        schedule_id,
        actor: actor.to_string(),
        source: source.to_string(),
        from_ts: from,
        to_ts: to,
        dry_run,
        total: i32::try_from(total).unwrap_or(i32::MAX),
        dispatched: i32::try_from(dispatched).unwrap_or(i32::MAX),
        skipped: i32::try_from(skipped).unwrap_or(i32::MAX),
        failed: i32::try_from(failed).unwrap_or(i32::MAX),
        status: status.to_string(),
        error_summary: error_summary.map(str::to_string),
        started_at,
        completed_at: Some(chrono::Utc::now()),
    };
    let _ = diesel::insert_into(harvest_backfill_log::table)
        .values(&row)
        .execute(&mut conn)
        .await;
}

/// Write an audit record; silently swallows errors.
#[allow(clippy::too_many_arguments)]
async fn write_audit(
    pool: &HarvestDbPool,
    actor: &str,
    source: &str,
    request_id: Option<&str>,
    route: &str,
    target_id: &str,
    status: &str,
    error_summary: Option<&str>,
) {
    let Ok(mut conn) = acquire_conn(pool.default_pool()).await else {
        return;
    };
    let ar = NewAuditRecord {
        actor,
        operation: OP_SCHEDULE_BACKFILL,
        target_type: TARGET_SCHEDULE,
        target_id: Some(target_id),
        route_or_command: route,
        request_id,
        idempotency_key: None,
        status,
        error_summary,
        shard_id: None,
        source,
    };
    let _ = audit::insert_audit(&mut conn, &ar).await;
}

/// Load a schedule row by UUID across all shards.
async fn load_schedule_by_id(
    api_state: &HarvestApiState,
    schedule_id: uuid::Uuid,
) -> Result<HarvestSchedule, AutumnError> {
    let (schedule, _shard) = load_schedule_by_id_with_shard(api_state, schedule_id).await?;
    Ok(schedule)
}

/// Like [`load_schedule_by_id`] but also returns the [`ShardId`] of the shard
/// the schedule was found on, so callers can route subsequent writes correctly.
///
/// Delegates to [`resolve_schedule_with_shard`] so every schedule lookup in the
/// plugin obeys one rule. The previous implementation `?`-propagated the first
/// shard's `acquire_conn` failure, so a schedule living on a *later* healthy
/// shard could not be found at all while an earlier shard was down — which took
/// down `GET /admin/schedules/{id}/preview` and `POST /admin/schedules/{id}/backfill`
/// (and, through them, the Vantage drill-downs) for rows that were perfectly
/// readable. The shared resolver keeps scanning, returns the row when any shard
/// has it, and distinguishes an authoritative `404` from a `503` when a shard
/// could not be checked — never an unqualified "not found" during an outage.
async fn load_schedule_by_id_with_shard(
    api_state: &HarvestApiState,
    schedule_id: uuid::Uuid,
) -> Result<(HarvestSchedule, ShardId), AutumnError> {
    resolve_schedule_with_shard(api_state, schedule_id).await
}

fn parse_schedule_expr_with_tz(
    expr: &str,
    timezone: &str,
) -> Result<autumn_harvest::policy::Schedule, String> {
    use autumn_harvest::policy::Schedule;

    let trimmed = expr.trim();
    let schedule = if let Some(rest) = trimmed.strip_prefix("cron_tz:") {
        // Canonical round-trip format emitted by GET /admin/schedules.
        // The embedded timezone takes precedence over the separate `timezone` field.
        let (tz, cron_expr) = rest.split_once(':').ok_or_else(|| {
            format!("malformed cron_tz expression '{expr}'; expected 'cron_tz:<tz>:<expr>'")
        })?;
        Schedule::CronInTimezone {
            expr: cron_expr.to_string(),
            tz: tz.to_string(),
        }
    } else if let Some(cron) = trimmed.strip_prefix("cron:") {
        let cron_expr = cron.trim().to_string();
        if timezone == "UTC" {
            Schedule::Cron(cron_expr)
        } else {
            Schedule::CronInTimezone {
                expr: cron_expr,
                tz: timezone.to_string(),
            }
        }
    } else if let Some(secs_str) = trimmed.strip_prefix("interval:") {
        let secs: u64 = secs_str
            .trim()
            .parse()
            .map_err(|_| format!("invalid interval seconds '{secs_str}'"))?;
        if secs == 0 {
            return Err("interval must be at least 1 second".to_string());
        }
        Schedule::Interval(std::time::Duration::from_secs(secs))
    } else if trimmed == "manual" {
        Schedule::Manual
    } else {
        // Treat a bare expression as a cron string for convenience.
        if timezone == "UTC" {
            Schedule::Cron(trimmed.to_string())
        } else {
            Schedule::CronInTimezone {
                expr: trimmed.to_string(),
                tz: timezone.to_string(),
            }
        }
    };
    // Validate cron expressions eagerly (including timezone names) so callers
    // receive a 400 rather than silently persisting an expression that will
    // never fire or an unknown timezone that would misfire.
    autumn_harvest::validate_schedule(&schedule)?;
    Ok(schedule)
}

#[derive(Debug, serde::Serialize)]
struct DeadLetterResponse {
    #[serde(flatten)]
    dead_letter: DeadLetter,
    runbook_url: Option<String>,
}

async fn list_dead_letters(
    Extension(api_state): Extension<HarvestApiState>,
    Query(query): Query<DeadLetterListQuery>,
    headers: axum::http::HeaderMap,
    maybe_session: Option<Extension<Session>>,
) -> Result<Json<Value>, AutumnError> {
    let limit = query.limit.unwrap_or(50).clamp(1, 200);
    // Read-path payload decoding (issue #608): the route is admin-gated, so
    // an arriving request passes the same predicate the decoder re-checks.
    let decoder = read_path_decoder(&api_state, extension_session(maybe_session)).await;
    // Issue #756: partial availability — an unreachable shard degrades to a
    // `200 partial` envelope naming `unavailable_shards` rather than a `500`.
    let FanoutRows {
        rows: mut dead_letters,
        status,
        unavailable_shards,
    } = load_dead_letters_from_shards(&api_state, limit, query.owner.as_deref()).await?;
    if let Some(codecs) = decoder.as_ref() {
        // Decode each row's JSONB input and TEXT error on the response copy
        // only; one audit row per request that touched ≥1 envelope.
        let mut outcome = LossyDecodeOutcome::default();
        for dl in &mut dead_letters {
            outcome = outcome.merged(codecs.decode_value_lossy(&mut dl.input));
            outcome = outcome.merged(decode_error_field(codecs, &mut dl.error));
        }
        // No live connection here: the per-shard DLQ loads are scoped inside
        // `load_dead_letters_from_shards`, so the pool-acquiring branch is
        // safe (PR #936 review).
        audit_decoded_read(
            &api_state,
            None,
            &headers,
            TARGET_DEAD_LETTER,
            None,
            "GET /dead-letters",
            None,
            outcome,
            None,
        )
        .await;
    }
    let dead_letters = dead_letters;

    let mut runbooks = std::collections::HashMap::new();
    let exec_ids: Vec<uuid::Uuid> = dead_letters
        .iter()
        .filter_map(|dl| dl.workflow_exec_id)
        .collect();

    if !exec_ids.is_empty() {
        let pool = api_state.storage_pool().map_err(map_error)?;
        let mut by_shard: std::collections::HashMap<_, Vec<uuid::Uuid>> =
            std::collections::HashMap::new();
        for id in exec_ids {
            let exec_id = ExecutionId::from_uuid(id);
            let shard = exec_id.shard();
            by_shard.entry(shard).or_default().push(id);
        }

        for (shard, ids) in by_shard {
            use autumn_harvest::schema::harvest_workflow_executions::dsl as wf_dsl;
            let shard_pool = pool.pool_for(shard);
            // Best-effort runbook enrichment (issue #756): a shard that goes
            // unreachable between the DLQ load and this secondary lookup must
            // not `500` the whole request — skip it; the dead-letter rows still
            // return, just without their runbook links.
            let Ok(mut conn) = acquire_conn(shard_pool).await else {
                continue;
            };
            let rows: Vec<(uuid::Uuid, Option<String>)> = match wf_dsl::harvest_workflow_executions
                .filter(wf_dsl::id.eq_any(&ids))
                .select((wf_dsl::id, wf_dsl::runbook_url))
                .load::<(uuid::Uuid, Option<String>)>(&mut conn)
                .await
            {
                Ok(rows) => rows,
                Err(_) => continue,
            };
            for (id, url) in rows {
                if let Some(u) = url {
                    runbooks.insert(id, u);
                }
            }
        }
    }

    let responses: Vec<DeadLetterResponse> = dead_letters
        .into_iter()
        .map(|dl| {
            let runbook_url = dl
                .workflow_exec_id
                .and_then(|id| runbooks.get(&id).cloned());
            DeadLetterResponse {
                dead_letter: dl,
                runbook_url,
            }
        })
        .collect();

    fanout_list_json("dead_letters", responses, status, &unavailable_shards)
}

/// `GET /dead-letters/aggregate` — root-cause aggregation for DLQ triage
/// (issue #385).
///
/// Groups dead-letter rows along a small named set of dimensions (`workflow_name`,
/// `activity_name`, `queue_name`, `task_type`, `time_bucket`, `failure_signature`)
/// and returns per-group counts plus a handful of representative
/// `dead_letter_id`s, fanning out across shards and merging the partials.
///
/// Partial availability (issue #756): the initial cut hard-`?`d each shard,
/// turning one unreachable shard into a `500`. It now collects-and-continues —
/// the merge runs over the reachable shards' partials and the response object
/// carries additive `status` + `unavailable_shards` fields (empty/`complete`
/// on the happy path).
async fn aggregate_dead_letters(
    Extension(api_state): Extension<HarvestApiState>,
    axum::extract::RawQuery(raw_query): axum::extract::RawQuery,
) -> Result<Json<Value>, AutumnError> {
    let pairs = crate::strict_query::decode_or_autumn_error(raw_query.as_deref())?;
    let params = dlq::DlqAggregateParams::from_query_pairs(&pairs, chrono::Utc::now())
        .map_err(AutumnError::bad_request_msg)?;

    let observations = observe_shards(&api_state, |_shard_id, mut conn| {
        let params = params.clone();
        async move {
            dlq::aggregate_dead_letters(&mut conn, &params)
                .await
                .map(|partial| vec![partial])
                .map_err(|e| e.to_string())
        }
    })
    .await?;

    let FanoutRows {
        rows: partials,
        status,
        unavailable_shards,
    } = collect_fanout_rows(observations);

    let merged = dlq::merge_dlq_aggregates(&params, partials);
    let mut value = serde_json::to_value(merged).map_err(|e| map_error(HarvestError::from(e)))?;
    if let Value::Object(map) = &mut value {
        map.insert(
            "status".to_string(),
            serde_json::to_value(status).map_err(|e| map_error(HarvestError::from(e)))?,
        );
        map.insert(
            "unavailable_shards".to_string(),
            serde_json::to_value(unavailable_shards)
                .map_err(|e| map_error(HarvestError::from(e)))?,
        );
    }
    Ok(Json(value))
}

async fn replay_dead_letter(
    Extension(api_state): Extension<HarvestApiState>,
    Path(id): Path<String>,
    headers: axum::http::HeaderMap,
) -> Result<(axum::http::StatusCode, Json<ReplayDeadLetterResponse>), AutumnError> {
    let (actor, source, request_id) = audit_context(&headers, &api_state);
    let route = "POST /dead-letters/{id}/replay";

    let dead_letter_id = match parse_uuid(&id, "dead-letter id") {
        Ok(u) => u,
        Err(e) => {
            if let Ok(pool) = api_state.storage_pool()
                && let Ok(mut conn) = acquire_conn(pool.default_pool()).await
            {
                let ar = NewAuditRecord {
                    actor: &actor,
                    operation: OP_DLQ_REPLAY,
                    target_type: TARGET_DEAD_LETTER,
                    target_id: Some(id.as_str()),
                    route_or_command: route,
                    request_id: request_id.as_deref(),
                    idempotency_key: None,
                    status: STATUS_FAILED,
                    error_summary: Some("malformed dead-letter id"),
                    shard_id: None,
                    source: &source,
                };
                let _ = audit::insert_audit(&mut conn, &ar).await;
            }
            return Err(e);
        }
    };
    let dl_id_str = dead_letter_id.to_string();

    let replay_result = replay_dead_letter_from_shards(&api_state, dead_letter_id).await;

    // For the single-replay path we insert the audit record on the default pool
    // since the DLQ entry may live on any shard and we don't track which one.
    let pool = api_state.storage_pool().map_err(map_error)?;
    let mut audit_conn = acquire_conn(pool.default_pool()).await?;

    match replay_result {
        Err(e) => {
            let err_str = e.to_string();
            let ar = NewAuditRecord {
                actor: &actor,
                operation: OP_DLQ_REPLAY,
                target_type: TARGET_DEAD_LETTER,
                target_id: Some(dl_id_str.as_str()),
                route_or_command: route,
                request_id: request_id.as_deref(),
                idempotency_key: None,
                status: STATUS_FAILED,
                error_summary: Some(err_str.as_str()),
                shard_id: None,
                source: &source,
            };
            let _ = audit::insert_audit(&mut audit_conn, &ar).await;
            Err(e)
        }
        Ok(task_id) => {
            let task_id_str = task_id.to_string();
            let ar = NewAuditRecord {
                actor: &actor,
                operation: OP_DLQ_REPLAY,
                target_type: TARGET_DEAD_LETTER,
                target_id: Some(dl_id_str.as_str()),
                route_or_command: route,
                request_id: request_id.as_deref(),
                idempotency_key: None,
                status: STATUS_SUCCEEDED,
                error_summary: None,
                shard_id: None,
                source: &source,
            };
            audit::insert_audit(&mut audit_conn, &ar)
                .await
                .map_err(map_error)?;
            Ok((
                axum::http::StatusCode::ACCEPTED,
                Json(ReplayDeadLetterResponse {
                    ok: true,
                    dead_letter_id: dl_id_str,
                    task_id: task_id_str,
                }),
            ))
        }
    }
}

struct ParsedBulkDlqRequest {
    selector: DlqBulkSelector,
    return_to: Option<String>,
    wants_redirect: bool,
}

#[derive(Debug, Clone, Default)]
struct DlqBulkSelector {
    filter: dlq::BulkDlqFilter,
    dead_letter_id: Option<uuid::Uuid>,
    task_type: Option<String>,
    shard_id: Option<i32>,
}

impl DlqBulkSelector {
    const fn is_empty(&self) -> bool {
        self.filter.is_empty()
            && self.dead_letter_id.is_none()
            && self.task_type.is_none()
            && self.shard_id.is_none()
    }

    const fn dry_run(&self) -> bool {
        self.filter.dry_run
    }
}

#[derive(Debug, Deserialize)]
struct BulkDlqApiBody {
    #[serde(default)]
    dead_letter_id: Option<uuid::Uuid>,
    #[serde(default)]
    activity_name: Option<String>,
    #[serde(default)]
    workflow_name: Option<String>,
    #[serde(default)]
    queue_name: Option<String>,
    #[serde(default)]
    min_attempts: Option<i32>,
    #[serde(default, alias = "task_kind")]
    task_type: Option<String>,
    #[serde(default)]
    failed_after: Option<chrono::DateTime<chrono::Utc>>,
    #[serde(default)]
    failed_before: Option<chrono::DateTime<chrono::Utc>>,
    #[serde(default)]
    error_class: Option<String>,
    #[serde(default)]
    dlq_reason: Option<String>,
    #[serde(default)]
    failure_signature: Option<String>,
    #[serde(default)]
    shard_id: Option<i32>,
    #[serde(default)]
    limit: Option<u32>,
    #[serde(default)]
    dry_run: bool,
}

impl BulkDlqApiBody {
    fn into_selector(self) -> Result<DlqBulkSelector, AutumnError> {
        let task_type = self
            .task_type
            .as_deref()
            .map(parse_dlq_task_type_filter)
            .transpose()?;
        Ok(DlqBulkSelector {
            filter: dlq::BulkDlqFilter {
                activity_name: self.activity_name,
                workflow_name: self.workflow_name,
                // `queue_name` is a plain positive-equality filter — treat empty
                // exactly like `activity_name`/`workflow_name` (a harmless
                // matches-nothing predicate), not like the strict-reject cause
                // dimensions (whose empty value would dangerously skip the
                // filter and widen the cohort).
                queue_name: self.queue_name,
                min_attempts: self
                    .min_attempts
                    .map(validate_bulk_min_attempts)
                    .transpose()?,
                failed_after: self.failed_after,
                failed_before: self.failed_before,
                error_class: normalize_cause_filter(self.error_class)?,
                dlq_reason: normalize_cause_filter(self.dlq_reason)?,
                failure_signature: normalize_cause_filter(self.failure_signature)?,
                limit: self.limit,
                dry_run: self.dry_run,
            },
            dead_letter_id: self.dead_letter_id,
            task_type,
            shard_id: self.shard_id,
        })
    }
}

/// Normalize a compute-on-read cause filter value (issue #613): an absent
/// value stays absent; a present value is trimmed and, if empty after
/// trimming, rejected with `400` rather than silently downgraded to "no
/// filter" (which would replay/discard a far larger cohort than intended).
fn normalize_cause_filter(value: Option<String>) -> Result<Option<String>, AutumnError> {
    value.map_or_else(
        || Ok(None),
        |raw| {
            let trimmed = raw.trim();
            if trimmed.is_empty() {
                Err(AutumnError::bad_request_msg(
                    "cause filter (error_class/dlq_reason/failure_signature) must not be empty",
                ))
            } else {
                Ok(Some(trimmed.to_string()))
            }
        },
    )
}

/// Validate a bulk-DLQ `min_attempts` filter (issue #613). The aggregate read
/// parser (`DlqAggregateParams::from_query_pairs`) only rejects negatives
/// (accepting `>= 0`), but the bulk replay/discard paths are DESTRUCTIVE so we
/// are stricter: attempt counts are 1-based, so a `min_attempts` of `0` or a
/// negative value produces the predicate `attempts >= 0` (or lower) which
/// matches EVERY DLQ row. That is not a genuine narrowing criterion, so it must
/// not satisfy the substantive-filter safety guard (AC8) — otherwise a
/// malformed request slips past `BulkDlqFilter::is_empty()` and acts on the
/// whole DLQ. Reject at the request boundary (mirroring `normalize_cause_filter`)
/// rather than touching the SQL predicate; require `>= 1`.
fn validate_bulk_min_attempts(value: i32) -> Result<i32, AutumnError> {
    if value < 1 {
        Err(AutumnError::bad_request_msg(format!(
            "invalid min_attempts '{value}'; expected a positive integer (>= 1)"
        )))
    } else {
        Ok(value)
    }
}

/// Parsed `POST /dlq/redrive` request (issue #510): the core filter plus the
/// API-only shard target and reason (which are not part of the shard-local
/// `RedriveFilter`).
struct RedriveRequest {
    filter: dlq::RedriveFilter,
    shard_id: Option<i32>,
    reason: Option<String>,
}

#[derive(Debug, Deserialize)]
struct RedriveApiBody {
    #[serde(default)]
    queue: Option<String>,
    #[serde(default)]
    workflow_name: Option<String>,
    #[serde(default)]
    dead_lettered_after: Option<chrono::DateTime<chrono::Utc>>,
    #[serde(default)]
    dead_lettered_before: Option<chrono::DateTime<chrono::Utc>>,
    #[serde(default)]
    error_contains: Option<String>,
    #[serde(default)]
    dead_letter_ids: Option<Vec<uuid::Uuid>>,
    #[serde(default)]
    max: Option<u32>,
    #[serde(default)]
    dry_run: bool,
    #[serde(default)]
    shard_id: Option<i32>,
    #[serde(default)]
    reason: Option<String>,
}

impl RedriveApiBody {
    fn into_request(self) -> RedriveRequest {
        RedriveRequest {
            filter: dlq::RedriveFilter {
                queue: self.queue,
                workflow_name: self.workflow_name,
                dead_lettered_after: self.dead_lettered_after,
                dead_lettered_before: self.dead_lettered_before,
                error_contains: self.error_contains,
                dead_letter_ids: self.dead_letter_ids,
                max: self.max,
                dry_run: self.dry_run,
            },
            shard_id: self.shard_id,
            reason: self.reason,
        }
    }
}

fn parse_bulk_dlq_request(
    headers: &axum::http::HeaderMap,
    body: &[u8],
) -> Result<ParsedBulkDlqRequest, AutumnError> {
    if is_form_urlencoded(headers) {
        parse_bulk_dlq_form(body)
    } else {
        let body = serde_json::from_slice::<BulkDlqApiBody>(body)
            .map_err(|e| AutumnError::bad_request_msg(format!("invalid JSON body: {e}")))?;
        Ok(ParsedBulkDlqRequest {
            selector: body.into_selector()?,
            return_to: None,
            wants_redirect: false,
        })
    }
}

fn is_form_urlencoded(headers: &axum::http::HeaderMap) -> bool {
    headers
        .get(axum::http::header::CONTENT_TYPE)
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.split(';').next())
        .is_some_and(|mime| {
            mime.trim()
                .eq_ignore_ascii_case("application/x-www-form-urlencoded")
        })
}

fn parse_bulk_dlq_form(body: &[u8]) -> Result<ParsedBulkDlqRequest, AutumnError> {
    let raw = std::str::from_utf8(body)
        .map_err(|_| AutumnError::bad_request_msg("form body must be valid UTF-8"))?;
    let mut selector = DlqBulkSelector::default();
    let mut return_to = None;

    for (key, value) in parse_urlencoded_form(raw)? {
        let field = key.trim();
        let value = value.trim();
        // Cause filters (issue #613) must be rejected — not silently skipped —
        // when empty, so an accidental empty form value can't widen the cohort
        // (the generic empty-value skip below would otherwise drop them).
        if matches!(field, "error_class" | "dlq_reason" | "failure_signature") {
            let normalized = normalize_cause_filter(Some(value.to_string()))?;
            match field {
                "error_class" => selector.filter.error_class = normalized,
                "dlq_reason" => selector.filter.dlq_reason = normalized,
                "failure_signature" => selector.filter.failure_signature = normalized,
                _ => unreachable!(),
            }
            continue;
        }
        if value.is_empty() {
            continue;
        }
        match field {
            "dead_letter_id" => {
                selector.dead_letter_id = Some(parse_uuid(value, "dead_letter_id")?);
            }
            "activity_name" => selector.filter.activity_name = Some(value.to_string()),
            "workflow_name" => selector.filter.workflow_name = Some(value.to_string()),
            "queue_name" => selector.filter.queue_name = Some(value.to_string()),
            "min_attempts" => {
                selector.filter.min_attempts = Some(validate_bulk_min_attempts(parse_i32_field(
                    value,
                    "min_attempts",
                )?)?);
            }
            "task_kind" | "task_type" => {
                selector.task_type = Some(parse_dlq_task_type_filter(value)?);
            }
            "failed_after" => {
                selector.filter.failed_after = Some(parse_utc_datetime(value, "failed_after")?);
            }
            "failed_before" => {
                selector.filter.failed_before = Some(parse_utc_datetime(value, "failed_before")?);
            }
            "limit" => selector.filter.limit = Some(parse_u32_field(value, "limit")?),
            "dry_run" => selector.filter.dry_run = parse_bool_field(value, "dry_run")?,
            "shard_id" => selector.shard_id = Some(parse_i32_field(value, "shard_id")?),
            "return_to" => return_to = Some(value.to_string()),
            _ => {}
        }
    }

    Ok(ParsedBulkDlqRequest {
        selector,
        return_to,
        wants_redirect: true,
    })
}

fn parse_urlencoded_form(raw: &str) -> Result<Vec<(String, String)>, AutumnError> {
    raw.split('&')
        .filter(|part| !part.is_empty())
        .map(|part| {
            let (key, value) = part.split_once('=').unwrap_or((part, ""));
            Ok((decode_form_component(key)?, decode_form_component(value)?))
        })
        .collect()
}

fn decode_form_component(input: &str) -> Result<String, AutumnError> {
    let bytes = input.as_bytes();
    let mut out = Vec::with_capacity(bytes.len());
    let mut index = 0;
    while index < bytes.len() {
        match bytes[index] {
            b'+' => {
                out.push(b' ');
                index += 1;
            }
            b'%' => {
                if index + 2 >= bytes.len() {
                    return Err(AutumnError::bad_request_msg(
                        "invalid percent-encoded form component",
                    ));
                }
                let high = hex_value(bytes[index + 1]).ok_or_else(|| {
                    AutumnError::bad_request_msg("invalid percent-encoded form component")
                })?;
                let low = hex_value(bytes[index + 2]).ok_or_else(|| {
                    AutumnError::bad_request_msg("invalid percent-encoded form component")
                })?;
                out.push((high << 4) | low);
                index += 3;
            }
            byte => {
                out.push(byte);
                index += 1;
            }
        }
    }

    String::from_utf8(out)
        .map_err(|_| AutumnError::bad_request_msg("form component must be valid UTF-8"))
}

const fn hex_value(byte: u8) -> Option<u8> {
    match byte {
        b'0'..=b'9' => Some(byte - b'0'),
        b'a'..=b'f' => Some(byte - b'a' + 10),
        b'A'..=b'F' => Some(byte - b'A' + 10),
        _ => None,
    }
}

fn parse_dlq_task_type_filter(value: &str) -> Result<String, AutumnError> {
    match value.trim().to_ascii_lowercase().as_str() {
        "activity" => Ok("ACTIVITY".to_string()),
        "workflow" => Ok("WORKFLOW".to_string()),
        other => Err(AutumnError::bad_request_msg(format!(
            "unknown task_type '{other}'; expected Activity or Workflow"
        ))),
    }
}

fn parse_utc_datetime(
    value: &str,
    field: &str,
) -> Result<chrono::DateTime<chrono::Utc>, AutumnError> {
    chrono::DateTime::parse_from_rfc3339(value)
        .map(|dt| dt.with_timezone(&chrono::Utc))
        .map_err(|_| {
            AutumnError::bad_request_msg(format!("invalid {field}; expected RFC 3339 timestamp"))
        })
}

fn parse_u32_field(value: &str, field: &str) -> Result<u32, AutumnError> {
    value.parse::<u32>().map_err(|_| {
        AutumnError::bad_request_msg(format!("invalid {field}; expected unsigned integer"))
    })
}

fn parse_i32_field(value: &str, field: &str) -> Result<i32, AutumnError> {
    value
        .parse::<i32>()
        .map_err(|_| AutumnError::bad_request_msg(format!("invalid {field}; expected integer")))
}

fn parse_bool_field(value: &str, field: &str) -> Result<bool, AutumnError> {
    match value.trim().to_ascii_lowercase().as_str() {
        "true" | "1" | "yes" | "on" => Ok(true),
        "false" | "0" | "no" | "off" => Ok(false),
        _ => Err(AutumnError::bad_request_msg(format!(
            "invalid {field}; expected boolean"
        ))),
    }
}

fn dlq_bulk_empty_filter_response(request: &ParsedBulkDlqRequest) -> axum::response::Response {
    use axum::response::IntoResponse as _;

    const MESSAGE: &str = "bulk filter must specify at least one criterion: dead_letter_id, \
                           activity_name, workflow_name, task_type, failed_after, failed_before, \
                           error_class, dlq_reason, failure_signature, or shard_id";

    if request.wants_redirect {
        return dlq_form_redirect(request.return_to.as_deref(), MESSAGE);
    }

    (
        axum::http::StatusCode::BAD_REQUEST,
        Json(serde_json::json!({ "error": MESSAGE })),
    )
        .into_response()
}

fn dlq_bulk_flash(result: &dlq::BulkDlqResult, verb: &str) -> String {
    if result.failures.is_empty() {
        format!(
            "{} dead-letter entr{} {verb}",
            result.acted_on,
            if result.acted_on == 1 { "y" } else { "ies" }
        )
    } else {
        format!(
            "{} dead-letter entries {verb}; {} failures",
            result.acted_on,
            result.failures.len()
        )
    }
}

struct DlqBulkAuditContext<'a> {
    actor: &'a str,
    source: &'a str,
    request_id: Option<&'a str>,
    operation: &'static str,
    route: &'static str,
    target_id: Option<&'a str>,
    shard_id: Option<i32>,
}

async fn insert_dlq_bulk_audit(
    api_state: &HarvestApiState,
    context: &DlqBulkAuditContext<'_>,
    status: &str,
    error_summary: Option<&str>,
) -> Result<(), AutumnError> {
    let pool = api_state.storage_pool().map_err(map_error)?;
    let mut conn = acquire_conn(pool.default_pool()).await?;
    let ar = NewAuditRecord {
        actor: context.actor,
        operation: context.operation,
        target_type: TARGET_DEAD_LETTER,
        target_id: context.target_id,
        route_or_command: context.route,
        request_id: context.request_id,
        idempotency_key: None,
        status,
        error_summary,
        shard_id: context.shard_id,
        source: context.source,
    };
    audit::insert_audit(&mut conn, &ar)
        .await
        .map(|_| ())
        .map_err(map_error)
}

fn dlq_form_redirect(return_to: Option<&str>, flash: &str) -> axum::response::Response {
    use axum::response::IntoResponse as _;

    axum::response::Redirect::to(&dlq_redirect_location(return_to, flash)).into_response()
}

fn dlq_redirect_location(return_to: Option<&str>, flash: &str) -> String {
    let base = return_to
        .map(str::trim)
        .and_then(safe_dlq_redirect_base)
        .unwrap_or_else(|| "../ui/dead-letters".to_string());
    let separator = if base.contains('?') { '&' } else { '?' };
    format!("{base}{separator}flash={}", url_encode_for_redirect(flash))
}

fn safe_dlq_redirect_base(value: &str) -> Option<String> {
    if is_dead_letter_ui_return_path(value, "../ui/dead-letters")
        || is_dead_letter_ui_return_path(value, "/api/harvest/ui/dead-letters")
    {
        Some(value.to_string())
    } else if is_dead_letter_ui_return_path(value, "ui/dead-letters") {
        Some(format!("../{value}"))
    } else {
        None
    }
}

fn is_dead_letter_ui_return_path(value: &str, prefix: &str) -> bool {
    match value.strip_prefix(prefix) {
        Some("") => true,
        Some(rest) => rest.starts_with('?'),
        None => false,
    }
}

fn url_encode_for_redirect(input: &str) -> String {
    let mut out = String::new();
    for byte in input.bytes() {
        if byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b'.' | b'~') {
            out.push(char::from(byte));
        } else {
            let _ = write!(out, "%{byte:02X}");
        }
    }
    out
}

async fn bulk_replay_dead_letters_handler(
    Extension(api_state): Extension<HarvestApiState>,
    headers: axum::http::HeaderMap,
    body: axum::body::Bytes,
) -> axum::response::Response {
    use axum::response::IntoResponse as _;

    let request = match parse_bulk_dlq_request(&headers, &body) {
        Ok(request) => request,
        Err(error) => return error.into_response(),
    };
    let (actor, mut source, request_id) = audit_context(&headers, &api_state);
    if request.wants_redirect && source == SOURCE_API {
        source = "ui".to_string();
    }
    let route = "POST /dead-letters/replay";

    if request.selector.is_empty() {
        dlq_bulk_audit_reject_empty_filter(
            &api_state,
            &actor,
            &source,
            request_id.as_deref(),
            OP_DLQ_REPLAY_BULK,
            route,
        )
        .await;
        return dlq_bulk_empty_filter_response(&request);
    }

    // Dry-run previews are read-only: no audit record needed.
    if request.selector.dry_run() {
        return match bulk_replay_from_shards(&api_state, &request.selector).await {
            Ok(result) => {
                if request.wants_redirect {
                    dlq_form_redirect(
                        request.return_to.as_deref(),
                        &dlq_bulk_flash(&result, "previewed"),
                    )
                } else {
                    (axum::http::StatusCode::OK, Json(result)).into_response()
                }
            }
            Err(e) => map_error(e).into_response(),
        };
    }

    let target_id = request.selector.dead_letter_id.map(|id| id.to_string());
    let shard_id = request.selector.shard_id;
    let replay_result = bulk_replay_from_shards(&api_state, &request.selector).await;
    let audit_context = DlqBulkAuditContext {
        actor: &actor,
        source: &source,
        request_id: request_id.as_deref(),
        operation: OP_DLQ_REPLAY_BULK,
        route,
        target_id: target_id.as_deref(),
        shard_id,
    };

    match replay_result {
        Ok(result) => {
            let status = if result.acted_on == 0 && !result.failures.is_empty() {
                axum::http::StatusCode::INTERNAL_SERVER_ERROR
            } else {
                axum::http::StatusCode::OK
            };
            let (audit_status, audit_error) = if result.failures.is_empty() {
                (STATUS_SUCCEEDED, None)
            } else {
                (
                    STATUS_FAILED,
                    Some(format!("{} failures", result.failures.len())),
                )
            };
            if let Err(error) = insert_dlq_bulk_audit(
                &api_state,
                &audit_context,
                audit_status,
                audit_error.as_deref(),
            )
            .await
            {
                return error.into_response();
            }
            if request.wants_redirect {
                dlq_form_redirect(
                    request.return_to.as_deref(),
                    &dlq_bulk_flash(&result, "replayed"),
                )
            } else {
                (status, Json(result)).into_response()
            }
        }
        Err(e) => {
            let err_str = e.to_string();
            let _ = insert_dlq_bulk_audit(
                &api_state,
                &audit_context,
                STATUS_FAILED,
                Some(err_str.as_str()),
            )
            .await;
            map_error(e).into_response()
        }
    }
}

