        let now = chrono::Utc::now();
        HarvestSchedule {
            id: uuid::Uuid::from_bytes([id_byte; 16]),
            dag_name: dag_name.map(ToOwned::to_owned),
            schedule_expr: Some("@hourly".to_string()),
            timezone: "UTC".to_string(),
            catchup: false,
            max_active_runs: 1,
            is_paused: false,
            last_run_at: None,
            next_run_at: None,
            created_at: now,
            updated_at: now,
            workflow_name: workflow_name.map(ToOwned::to_owned),
            workflow_input: None,
            queue_name: None,
            paused_at: None,
            paused_by: None,
            pause_reason: None,
            jitter_secs: 0,
            overlap_policy: "skip".to_string(),
            buffered_runs: serde_json::json!([]),
            buffer_all_max: 0,
            calendar_name: None,
            skip_policy: "skip".to_string(),
            fire_claim_token: None,
            fire_claimed_until: None,
            consecutive_failure_limit: None,
            consecutive_failure_count: 0,
            auto_paused_at: None,
            end_at: None,
            max_runs: None,
            runs_started: 0,
            exhausted_at: None,
            exhausted_reason: None,
            catchup_policy: None,
            catchup_window_secs: None,
            last_catchup_dropped: 0,
            last_catchup_at: None,
            retry_policy: None,
        }
